/* Types */
/**  What the credential may do at most. */
export type AccessCap = "write" | 
/**  A read-only token, a phone paired as a reader, a read link. */
"read";

/**  What `access_set` writes on each path. */
export type AccessChange = 
/**
 *  The path's whole set; on a folder, it replaces everything inside
 *  (earlier exceptions included) unless `keep_exceptions` is true.
 */
{ kind: "set"; set: AccessSetView; 
/**  `Some` to turn the secret name on or off; `None` leaves it. */
secret_name: boolean | null; 
/**
 *  On a folder: the files and folders inside that have a set of
 *  their own keep it, untouched, in the same transaction (the
 *  window's *Manter*). False: everything inside is replaced.
 */
keep_exceptions?: boolean } | 
/**  *Follow the folder*: the path's own set is deleted. */
{ kind: "follow" };

/**
 *  Access changed, told to every window on the folder (event
 *  `access-changed`), per player as `campaign-changed` is: the window asks
 *  again what it shows.
 */
export type AccessChanged = {
	/**  The paths whose access changed (empty when a table or a right did). */
	paths: string[],
};

/**  A file or subfolder with an access set of its own inside a folder. */
export type AccessException = {
	path: string,
	folder: boolean,
	set: AccessSetView,
};

/**  The access of one path (`access_get`). */
export type AccessInfo = {
	path: string,
	folder: boolean,
	/**  The table that holds the path (its `root`); empty when none. */
	table: string,
	/**  The path's own set; none while it follows its folder. */
	own: AccessSetView | null,
	/**  What applies now: its own, else its folder's, else hidden. */
	set: AccessSetView,
	why: AccessWhy,
	/**  For a folder: how many files lie under it (what *Apply* changes). */
	files: number,
	/**  For a folder: the files and subfolders with a set of their own. */
	exceptions: AccessException[],
	/**  The note's name is a secret (links to it show as blocks). */
	secret_name: boolean,
	/**  How many secret blocks the note holds: whoever edits sees them. */
	secret_blocks: number,
	/**  The table's players (to a player, only the ones who have access). */
	players: AccessPlayer[],
	/**  Whether the person asking may change it (the game master). */
	manage: boolean,
	/**  The game master's name: the one who always has access. */
	master: string,
};

/**  How much of a path a person has. */
export type AccessLevel = 
/**  Does not see it: to them it does not exist. */
"none" | 
/**  Sees it, reads it. */
"see" | 
/**  Sees it and edits it. */
"edit";

/**  A player of the table, as the access dialog lists them. */
export type AccessPlayer = {
	id: string,
	name: string,
	/**  A folder's editor: a player who edits every file they see. */
	editor: boolean,
	/**  The one asking (a player's own row). */
	you: boolean,
};

/**  One player's level in a set. */
export type AccessRow = {
	account: string,
	level: AccessLevel,
};

/**  Who a person is at a folder's table. */
export type AccessSeat = 
/**  The folder's owner. */
"master" | 
/**  An editor or a reader of the folder. */
"player" | 
/**  A read link's visitor. */
"visitor" | 
/**  No place here (a folder with no table counts the role below). */
"none";

/**  What `access_set` answers. */
export type AccessSetResult = {
	/**  How many files changed their access. */
	changed: number,
};

/**
 *  The whole access of a path: the *Whole table* level and the players
 *  whose level differs (ADR 0113 item 2).
 */
export type AccessSetView = {
	whole: AccessLevel,
	rows: AccessRow[],
};

/**
 *  Where a level comes from, so the window can word it and never
 *  recompute it.
 */
export type AccessWhy = 
/**  The game master: always. */
{ kind: "master" } | 
/**  No table: the folder's role decides. */
{ kind: "role" } | 
/**  The path's own set. */
{ kind: "own" } | 
/**  A folder's set, the nearest above. */
{ kind: "folder"; path: string } | 
/**  No set anywhere: the table's default, hidden. */
{ kind: "default" } | 
/**  An attachment no set covers, shown by a file the person sees. */
{ kind: "derived" } | 
/**  The table is closed to players. */
{ kind: "closed" };

/**
 *  The AI command-line tools the terminal offers to start (ADR 0115 item
 *  14, Q3 decided 2026-10-31; OpenCode and Cursor's CLI added by the
 *  maintainer the same day), each by the command its maker installs. A
 *  fixed list: the window names one, the host knows the word. A tool more
 *  is a variant here, its word and page in the host (`pty::cli_word`,
 *  `terminal::install_page`) and its name in the window's strings.
 */
export type AiCli = 
/**  Claude Code, `claude`. */
"claude" | 
/**  Gemini CLI, `gemini`. */
"gemini" | 
/**  Codex, `codex`. */
"codex" | 
/**  Antigravity's CLI, `agy`. */
"antigravity" | 
/**  OpenCode, `opencode`. */
"opencode" | 
/**  Cursor's CLI, `cursor-agent`. */
"cursor_agent";

/**
 *  Whether the person's login shell finds an AI command-line tool (ADR 0115
 *  item 14): asked on a click, never at start.
 */
export type AiCliFound = {
	cli: AiCli,
	found: boolean,
};

/**
 *  What the running app is: its version (the workspace's, ADR 0051) and the
 *  commit it was built from — shown in the settings and the About panel.
 */
export type AppInfo = {
	version: string,
	commit: string,
	/**
	 *  This computer's name, as the copy of a conflict names it (ADR 0079
	 *  item 8): the editor's "keep both" names its copy as sync does.
	 *  None where the window runs on no computer of its own (a server).
	 */
	device: string | null,
};

/**
 *  What `audio_share_start` answers once the host captures and encodes: the
 *  source and the shape of the frames it will hand the window.
 */
export type AudioCaptureStarted = {
	source: AudioSource,
	bitrate_kbps: number,
	sample_rate: number,
	channels: number,
	frame_ms: number,
};

/**
 *  A table's live share as everyone at the table sees it (events
 *  `table-share-started` and `table-share-state`, `TableJoin.share`, the
 *  answer of `table_share_start`). The server stamps it.
 */
export type AudioShare = {
	/**
	 *  The table: its folder inside the server's folder, `""` for the
	 *  folder itself (as `TableEntry.table`).
	 */
	table: string,
	/**
	 *  The share's number, in every binary frame's header. Never reused by
	 *  a table in one server run.
	 */
	id: number,
	/**  The source's name, as the sharer's host gave it. */
	name: string,
	kind: AudioSourceKind,
	/**  Who shares: the name and the opaque account, stamped by the server. */
	by: string,
	by_id: string,
	/**  When it started, the server's clock, Unix milliseconds. */
	started_ms: number | null,
	bitrate_kbps: number,
	/**
	 *  To the sharer only (none to everyone else): how many windows are
	 *  receiving.
	 */
	listeners: number | null,
	/**  To the sharer only: the rate leaving the server for them, in bit/s. */
	rate_bps: number | null,
};

/**  Why a share ended. */
export type AudioShareEnd = 
/**  The sharer pressed Stop. */
"stopped" | 
/**  The sharer's window disconnected. */
"sharer_left" | 
/**  The last window left the table. */
"table_empty" | 
/**  The sharer started another source in its place. */
"replaced";

/**
 *  The sharer's window asks the server to start a share (`table_share_start`):
 *  what to call it, what kind of source it is, the bitrate it encodes at.
 *  The server checks the closed form ([`name_ok`], [`bitrate_ok`]) and
 *  `may(Broadcast)`; one share per table, and `replace` says the sharer
 *  agrees to end the table's current one (item 16).
 */
export type AudioShareStart = {
	name: string,
	kind: AudioSourceKind,
	bitrate_kbps: number,
	replace?: boolean,
};

/**  A share ended (event `table-share-stopped`). */
export type AudioShareStopped = {
	table: string,
	id: number,
	reason: AudioShareEnd,
};

/**
 *  One thing the host can capture (`audio_sources_list`). `id` is the
 *  host's own opaque handle, good for the host's next `audio_share_start`
 *  and meaningless elsewhere; `name` is at most [`SOURCE_NAME_MOST`]
 *  characters of plain text, an application's display name, never a window
 *  title.
 */
export type AudioSource = {
	id: string,
	name: string,
	kind: AudioSourceKind,
};

/**  What kind of thing a source is. */
export type AudioSourceKind = 
/**  An application (the Spotify app, a browser). */
"app" | 
/**  A page open in Verso itself (a child web view, ADR 0056). */
"page" | 
/**
 *  Everything this computer plays (minus Verso's own sounds where the
 *  system allows it).
 */
"system";

/**  Who a version names (item 4). */
export type AuthorKind = 
/**  An account of the server, by its name. */
"account" | 
/**  A device of an account, by the device's name. */
"device" | 
/**  An agent's token, by the token's name. */
"agent" | 
/**  This computer, by its name: a version of a folder of the computer. */
"computer" | 
/**  A change the watcher found, made outside Verso. */
"outside";

/**  A link into a note, from another. */
export type Backlink = {
	from: string,
	target: string,
	embed: boolean,
	line: number,
	col: number,
};

/**  A value as a view shows it. */
export type BaseCell = { kind: "empty" } | { kind: "text"; value: string } | { kind: "number"; value: number | null } | { kind: "bool"; value: boolean } | 
/**
 *  A wall-clock time in the window's zone, in milliseconds since
 *  1970-01-01T00:00 of that clock (read it with UTC getters), and
 *  whether it has a time of day.
 */
{ kind: "date"; value: {
	ms: number | null,
	time: boolean,
} } | 
/**  Milliseconds. */
{ kind: "duration"; value: number | null } | { kind: "list"; value: BaseCell[] } | { kind: "object"; value: ([string, BaseCell])[] } | 
/**  A link as written, the text to show, and the file it resolves to. */
{ kind: "link"; value: {
	target: string,
	display: string | null,
	path: string | null,
} } | { kind: "file"; value: string } | 
/**  A path relative to the folder, or a URL. */
{ kind: "image"; value: string } | { kind: "icon"; value: string } | { kind: "html"; value: string } | { kind: "error"; value: {
	kind: BaseErrorKind,
	name: string,
} };

/**
 *  A column: the property id as the view writes it (`file.name`,
 *  `status`, `formula.x`), and the name the base gives it, if any.
 */
export type BaseColumn = {
	id: string,
	name: string | null,
};

/**  An evaluation's error: its kind and what it concerns. */
export type BaseError = {
	kind: BaseErrorKind,
	name: string,
};

/**  Why a value could not be computed. */
export type BaseErrorKind = "syntax" | "unknownFunction" | "unknownMethod" | "arguments" | "type" | 
/**
 *  A regular expression where the method takes a text (`contains`,
 *  `startsWith`); `name` is the method (ADR 0094 item 1).
 */
"regex" | 
/**
 *  Not a regular expression, or a flag that is no flag; `name` is the
 *  literal as written.
 */
"regexInvalid" | 
/**
 *  What the engine does not have; `name` is `lookahead`,
 *  `lookbehind`, `backreference`, `flag y`, `flag d` or `flag v`
 *  (ADR 0094 items 2 and 4).
 */
"regexUnsupported" | 
/**
 *  A pattern past 1,000 characters or its compiled size, or one too
 *  many in a query; `name` is the literal (ADR 0094 item 3).
 */
"regexTooLarge" | "cycle" | "budget" | "tooLarge";

export type BaseGroup = {
	/**  The grouping property's value; `None` when the view is not grouped. */
	key: BaseCell | null,
	rows: BaseRow[],
	/**  One per column: the summary the view asks for, if any. */
	summaries: (BaseCell | null)[],
};

/**
 *  Something about the base as a whole, shown once above the view;
 *  `detail` is what it concerns, as written in the base.
 */
export type BaseProblem = {
	kind: BaseProblemKind,
	detail: string,
	/**  Why an evaluation failed, as its cells say it (ADR 0094 item 5). */
	error: BaseError | null,
};

export type BaseProblemKind = "notABase" | "tooLong" | "shape" | "expression" | "evaluation" | "unknownView" | "budget";

/**
 *  A base to evaluate (ADR 0053): a `.base` file, or the text of a `base`
 *  block of a note; the view to show; the window's clock and language.
 */
export type BaseQuery = {
	/**  The `.base` file, relative to the folder, when the base is one. */
	path: string | null,
	/**
	 *  The base's text, when it is a block of a note: read instead of
	 *  `path`.
	 */
	text: string | null,
	/**
	 *  The file `this` stands for: the note a base is embedded in, or the
	 *  `.base` file itself.
	 */
	this: string | null,
	/**  The view, by name; the first when absent. */
	view: string | null,
	/**
	 *  Properties to evaluate besides the view's `order`: what the layout
	 *  draws (a card's image, a calendar's date).
	 */
	extra: string[],
	/**  The window's clock: milliseconds since the Unix epoch. */
	now: number | null,
	/**  The window's zone: minutes east of UTC. */
	offset: number,
	/**  The interface language (`pt-BR`, `en`). */
	lang: string,
};

/**  A base evaluated. */
export type BaseResult = {
	/**  Every view of the base, in order. */
	views: BaseView[],
	/**
	 *  The view evaluated, as an index into `views`; `None` when the base
	 *  has none and a table of every file was evaluated.
	 */
	view: number | null,
	columns: BaseColumn[],
	/**  The rows; one group when the view is not grouped. */
	groups: BaseGroup[],
	/**  Files that passed the filters, before the view's `limit`. */
	total: number,
	problems: BaseProblem[],
	/**
	 *  Every note property of the folder, once each: what the view's
	 *  menus offer.
	 */
	properties: string[],
};

export type BaseRow = {
	path: string,
	/**  A Markdown note: its properties may be changed from the view. */
	note: boolean,
	/**  One per column. */
	cells: BaseCell[],
};

export type BaseView = {
	name: string,
	/**
	 *  `table`, `cards`, `list`, `kanban`, `calendar`, or one Verso does
	 *  not draw.
	 */
	kind: string,
};

/**  A `^id` block of a note (ADR 0018: cite this instead of a position). */
export type Block = {
	id: string,
	line: number,
	col: number,
	/**
	 *  The first and last line of the block the id names (spec Q3, Q21):
	 *  what a link `[[nota#^id]]` reaches and an embed of it shows.
	 */
	first_line: number,
	last_line: number,
};

/**  What a block with an `^id` is, read from its first line. */
export type BlockKind = "paragraph" | "list" | "table" | "heading" | "quote" | "code";

/**
 *  Who has access to a note of a table (`campaign_access`, ADR 0110
 *  item 4 as amended 2026-10-23): the note's audience and, per player, what
 *  they can do. To the game master every player is listed, those without
 *  access too; to a player only the ones who have it, and never the
 *  game master's controls.
 */
export type CampaignAccess = {
	path: string,
	/**  `owner` or `player`. */
	viewer: string,
	audience: CampaignAudience,
	people: CampaignPerson[],
	/**  The game master's name: the one who always has access. */
	master: string,
};

/**
 *  Who a note is released to (ADR 0110 item 4, amended 2026-10-23): nobody,
 *  the whole table, or a set of the table's players.
 */
export type CampaignAudience = 
/**  Nobody but the game master. */
{ kind: "hidden" } | 
/**  Every player at the table, and those who join later. */
{ kind: "table" } | 
/**  These players, by account. */
{ kind: "players"; accounts: string[] };

/**
 *  Notes released or hidden, told to every window on the folder (event
 *  `campaign-changed`): the window reads `campaign_status` again, and a
 *  player's file tree reloads.
 */
export type CampaignChanged = {
	/**  The paths whose state changed (empty when a table changed). */
	paths: string[],
};

/**  Who may edit a note besides the game master (ADR 0110 item 5). */
export type CampaignGrant = 
/**  Nobody: the players read it. */
{ kind: "none" } | 
/**  Every player at the table. */
{ kind: "group" } | 
/**  One player, by account. */
{ kind: "player"; account: string };

/**
 *  An invitation to a table (`campaign_invite`): a link to copy, single
 *  use, seven days.
 */
export type CampaignInvite = {
	link: string,
	/**  Unix seconds. */
	expires: number,
};

/**
 *  What the server keeps about a note of a table (ADR 0110 items 4, 5, 7).
 *  A note with no entry is hidden, with no grant and an ordinary name.
 */
export type CampaignNote = {
	path: string,
	/**  Whether any player sees it: the audience is not `hidden`. */
	released: boolean,
	/**  Who sees it. */
	audience: CampaignAudience,
	/**  Every link to it is drawn as four blocks, whatever was written. */
	secret_name: boolean,
	grant: CampaignGrant,
	/**
	 *  The players who see it, by account (ADR 0113): every one of them,
	 *  whatever the audience can say. To the game master.
	 */
	sees?: string[],
	/**  The players who edit it, by account. */
	edits?: string[],
};

/**  What one person at a table can do with a note (`campaign_access`). */
export type CampaignPerson = {
	id: string,
	name: string,
	/**  `edits`, `sees` or `none`. */
	access: string,
	/**
	 *  Whether this person is the one asking: a player's own row, which the
	 *  window words as "you". Always false for the game master's list.
	 */
	you: boolean,
};

/**  A player of a table: an account that may open the table's folder. */
export type CampaignPlayer = {
	id: string,
	name: string,
	/**
	 *  The tables (their `root`) this account plays at; to the game master
	 *  only, empty when the server did not say (an older one).
	 */
	roots?: string[],
};

/**
 *  What `campaign_status` answers. To the folder's owner: every table of
 *  the folder, the state of its notes and its players. To a player: the
 *  tables it can open, and only the notes it may edit.
 */
export type CampaignStatus = {
	/**  `owner`, `player` or `none` (a folder with no table). */
	viewer: string,
	tables: CampaignTable[],
	notes: CampaignNote[],
	players: CampaignPlayer[],
	/**
	 *  Whether this account may make an invitation link for a person who
	 *  has no account yet (only the server's admin may: ADR 0081 item 4).
	 */
	can_invite: boolean,
};

/**  A folder made a table (ADR 0110 item 1). */
export type CampaignTable = {
	/**
	 *  The table's folder, relative to the open folder; `""` is the whole
	 *  folder.
	 */
	root: string,
	/**  Open to sign-in; closed, the players cannot open it (MC.1 = A). */
	open: boolean,
	/**  The table log's ceiling (1,000 to 200,000 entries; MS.1). */
	log_max: number,
	/**  The file size limit, in bytes (1 to 30 MB; MS.1): any file *Images* or *Files* carries. */
	image_max: number,
	/**
	 *  To the game master: the players this table lets send an image to its
	 *  chat (the right *Images*, ADR 0113 K.6). Empty to a player.
	 */
	image_players?: string[],
	/**
	 *  To the game master: the players given *Files* — a file that is not an
	 *  image, to the chat and into the files they edit (K.6).
	 */
	file_players?: string[],
	/**  To the game master: the players given *Creates notes* (K.6). */
	note_players?: string[],
	/**  To the game master: the players given *Creates boards* (K.6). */
	board_players?: string[],
	/**
	 *  Whether this account may send an image at the table: always the
	 *  game master, a player only when it was given the right.
	 */
	images?: boolean,
	/**  Whether this account may send a file that is not an image. */
	files?: boolean,
};

/**
 *  What the side the window talks to can do (ADR 0027; ADR 0076 item 11):
 *  the window hides what is absent instead of showing it and failing.
 */
export type Can = 
/**  Change the open folder (a reader on a server cannot). */
"write" | 
/**  Show a file in the system's file manager. */
"reveal" | 
/**  Copy a file's full path. */
"copy_path" | 
/**  Open windows of the app: a note in one of its own, a new window. */
"windows" | 
/**  Show web pages inside the window (child web views). */
"web_views" | 
/**  The command line and the agents of the settings (ADR 0054). */
"agents" | 
/**  The app's own updates (ADR 0055). */
"updates" | 
/**  The window's console. */
"devtools" | 
/**  Open folders from this computer's disk. */
"local_folders" | 
/**  An account signed in on a server: the account's page. */
"account" | 
/**  The account is the server's admin: the admin page. */
"admin" | 
/**  Several people editing one note at once (ADR 0073 item 7). */
"collab" | 
/**
 *  The side shows a folder, with its index: the tree, the graph, the
 *  bases, the tags, the files. Absent for one file opened without a
 *  folder (ADR 0114 items 18 and 25), as are the rest below.
 */
"index" | 
/**  Full-text search over the folder. */
"search" | 
/**  Backlinks and unlinked mentions. */
"backlinks" | 
/**  New notes, files and folders. */
"create" | 
/**  Renaming and moving entries. */
"rename" | 
/**  Deleting entries (into the bin). */
"delete" | 
/**  The folder's bin (ADR 0080). */
"trash" | 
/**  Version history (ADR 0091). */
"history" | 
/**  Sync with a server or a cloud (ADR 0079, ADR 0104). */
"sync" | 
/**  The table: rolls and chat (ADR 0107). */
"table" | 
/**  Boards and drawings (ADR 0057). */
"board" | 
/**
 *  A shell of this computer in a tab (ADR 0115 item 6): the desktop
 *  host alone lists it, in every window of a folder — of this computer,
 *  or a server's, whose shell starts in the person's home directory —
 *  and never a server, the web window, the phone, or a window of files
 *  opened without their folder (ADR 0114 item 9).
 */
"terminal" | 
/**
 *  Share the sound of an application, a page or the system with the
 *  table (ADR 0116 section B, item 27): captured by the desktop host
 *  only. Not in [`Can::FOLDER`]: a server, a phone and a window of loose
 *  files never list it, and where it is absent *Share audio…* is not
 *  drawn.
 */
"audio_share";

export type Capabilities = Capabilities_Serialize | Capabilities_Deserialize;

export type Capabilities_Deserialize = {
	host: Host,
	can: Can[],
	/**
	 *  The round trip to the side, in milliseconds, when it is across a
	 *  network (the desktop app on a server's folder, ADR 0073 item 2): the
	 *  window learns how far the core is (ADR 0026 rule 2).
	 */
	latency_ms: number | null,
	/**
	 *  Who the person is at the open folder's table (ADR 0113): the one
	 *  source of "who am I here". A host with no server says nothing: the
	 *  folder is the person's own.
	 */
	access?: FolderAccess | null,
};

export type Capabilities_Serialize = {
	host: Host,
	can: Can[],
	/**
	 *  The round trip to the side, in milliseconds, when it is across a
	 *  network (the desktop app on a server's folder, ADR 0073 item 2): the
	 *  window learns how far the core is (ADR 0026 rule 2).
	 */
	latency_ms: number | null,
	/**
	 *  Who the person is at the open folder's table (ADR 0113): the one
	 *  source of "who am I here". A host with no server says nothing: the
	 *  folder is the person's own.
	 */
	access?: FolderAccess | null,
};

/**
 *  What stands where the app installs its command line (ADR 0054):
 *  `/usr/local/bin/verso`, on the PATH every shell has.
 */
export type CliState = 
/**  A link to this app's own command line. */
"ours" | 
/**  Nothing. */
"missing" | 
/**  Something else: another link, a copy put there by hand. */
"elsewhere" | 
/**
 *  This build carries no command line to link (a development build
 *  without it).
 */
"unbundled" | 
/**
 *  Windows: the command line comes with the app, `verso.exe` beside
 *  it, and nothing is linked onto a PATH (ADR 0069, item 9).
 */
"bundled";

/**
 *  The answer to checking a cloud before the folder syncs with it (ADR
 *  0104 items 7 and 16): whether the service can keep the folder's edits
 *  safe, and what is there already. Nothing is saved when it is not
 *  `accepted`.
 */
export type CloudCheck = {
	accepted: boolean,
	/**
	 *  When not accepted, why, for the window to say in its language:
	 *  `plain_http_unconfirmed`, `plain_http_refused`, `invalid`,
	 *  `auth`, `unreachable`, `service_refused`, `no_conditional_delete`,
	 *  `no_keyring`, `failed`.
	 */
	problem: string | null,
	/**  The reason in English, for the log and as the window's fallback. */
	message: string | null,
	/**  Where, in a few words. */
	label: string,
	/**  What a deletion there means: `final`, `kept` or `unknown`. */
	deletions: string,
	/**  Things found that are not a refusal. */
	notes: string[],
	/**  The space left on the service, when it says (bytes). */
	free: number | null,
	/**  What is in the cloud's folder already. */
	remote_files: number | null,
	remote_bytes: number | null,
};

/**
 *  What the person typed into the form to sync a folder with a cloud
 *  (ADR 0104 item 6), except the secret — a password, an S3 secret key —
 *  which crosses once in the check ([`CloudCheck`]) and is kept by the
 *  host in the system's keychain.
 */
export type CloudSettings = {
	/**  `webdav` or `s3`. */
	provider: string,
	/**
	 *  WebDAV: the folder's address. S3: the endpoint's address, empty
	 *  for AWS.
	 */
	endpoint: string,
	/**  S3: the bucket, and a prefix inside it. */
	bucket: string,
	prefix: string,
	/**  S3: the region requests are signed for. */
	region: string,
	/**  WebDAV: the user. S3: the access key's id. */
	user: string,
	/**  S3: the bucket in the path (MinIO and most self-hosted services). */
	path_style: boolean,
	/**
	 *  The person confirmed that a plain-HTTP address on the local
	 *  network is theirs.
	 */
	plain_http: boolean,
};

/**
 *  A cloud a folder syncs with, as its window shows it (ADR 0104 item
 *  16). The secret is not here and never will be: it is in the system's
 *  keychain, and the window sends it once and never reads it back (ADR
 *  0026).
 */
export type CloudStatus = {
	/**  `webdav` or `s3`. */
	provider: string,
	/**
	 *  Where, in a few words: the server and folder, or the bucket and
	 *  prefix.
	 */
	label: string,
	/**
	 *  What deleting a file there means (item 9, said when the person
	 *  connected): `final`, `kept` (the bucket keeps earlier versions) or
	 *  `unknown`.
	 */
	deletions: string,
	/**  What the checks at connecting found that the person should know. */
	notes: string[],
};

/**
 *  A file joined for editing by several people at once (ADR 0073 item 7,
 *  ADR 0082 item 12): the shared state as a Yjs update (base64) to apply
 *  to an empty document, the revision on disk it stands on, and how the
 *  file is written — a text's lines in the shared state end in `\n`; a
 *  file that mixes them is shown read-only and joins nothing.
 */
export type CollabJoin = {
	/**
	 *  A text or a board: the window binds the state to its editor or to
	 *  its board by it.
	 */
	kind: CollabKind,
	update: string,
	revision: string,
	read_only: boolean,
	/**  Whether the file's lines end in CRLF. */
	crlf: boolean,
	/**  The name the others see for this person. */
	user: string,
	/**
	 *  Which room this is: a window that comes back after its connection
	 *  dropped sends what it typed meanwhile only into the room it left,
	 *  never into one made again from the disk.
	 */
	epoch: string,
	/**
	 *  The room's last rolls of dice, oldest first, for whoever joins
	 *  (ADR 0088 item 4): kept in the server's memory, never stored.
	 */
	rolls?: DiceRoll[],
};

/**
 *  What a room holds (ADR 0082 item 12, decided 2026-10-12): a `text` —
 *  a note, or any other text file of the folder — as one Yjs text, or a
 *  `board` as its elements, one entry per element and version.
 */
export type CollabKind = "text" | "board";

/**
 *  An oracle draw in a room, heard by the others in it (event
 *  `collab-oracle`).
 */
export type CollabOracle = {
	path: string,
	draw: OracleDraw,
};

/**
 *  A roll in a room, heard by the others in it (event `collab-roll`).
 *  The roll carries no path: the event's is the window's own.
 */
export type CollabRoll = {
	path: string,
	roll: DiceRoll,
};

/**
 *  What became of a shared note (events `collab-saved`, `collab-conflict`,
 *  `collab-closed`): written at `revision`; changed on disk while edits
 *  waited, so the people in it see the difference; or no longer shared
 *  (renamed, deleted, its line ends mixed), so the window reads it again.
 */
export type CollabState = {
	path: string,
	revision: string | null,
};

/**
 *  An edit or a presence of another person in a note (events
 *  `collab-update` and `collab-awareness`): a Yjs update, base64.
 */
export type CollabUpdate = {
	path: string,
	update: string,
};

/**
 *  An error as the UI receives it. `message` is the core's text, in
 *  English: which language it should speak is the UI's `[OPEN]` under
 *  ADR 0035, recorded here rather than decided.
 */
export type ContractError = {
	kind: ErrorKind,
	message: string,
};

/**
 *  This computer's name (ADR 0079 item 8, ADR 0074 item 8; decided
 *  2026-10-11): the one the person set in Settings › Servers, or the
 *  system's. A conflict's copy carries it, and a server's list of sessions
 *  and its change log show it.
 */
export type DeviceName = {
	/**  The name in use: the person's when set, the system's otherwise. */
	name: string,
	/**  The system's name, the default. */
	system: string,
	/**  Whether the person set the name. */
	custom: boolean,
};

/**
 *  The name set, and the servers this computer is signed in to that could
 *  not be told: their list of sessions keeps the old name until the next
 *  sign-in there.
 */
export type DeviceRenamed = {
	device: DeviceName,
	/**  The addresses of the servers not reached. */
	unreached: string[],
};

/**
 *  A roll of dice (ADR 0088): the notation rolled, the table it chose a
 *  row of when it was one, what each die showed, and the total. In a room
 *  the server rolls and names who asked; alone, the window rolls and
 *  `by` is empty. Never written to a file (item 2).
 */
export type DiceRoll = {
	/**  What was rolled, without spaces: `1d20+3`, `4d6kh3`. */
	notation: string,
	/**
	 *  The random table rolled, as the note writes it (`[[Tabelas#^id]]`):
	 *  the window that hears the roll reads the row from the table itself.
	 */
	source: string | null,
	/**  Each term of dice in the notation's order. */
	terms: DiceTermRoll[],
	/**  The numbers added to the dice, summed. */
	modifier: number,
	total: number,
	/**  The name of the account that rolled; empty when the window rolled. */
	by: string,
	/**  When, RFC 3339 in UTC. */
	at: string,
	/**
	 *  The roller's dice appearance, as the window sent it and the server
	 *  checked it (ADR 0107 item 11); none when the window rolled alone or
	 *  sent none.
	 */
	styles?: DiceStyles | null,
	/**
	 *  Which of the note's dice with this code was clicked, from the first
	 *  (ADR 0107): a note can hold the same `dice:` code twice, and a
	 *  window that hears the roll shows it on that one. For display only;
	 *  none when the roll was not made from a die in a note, or by an older
	 *  window or server, and then the first such die shows it.
	 */
	occurrence?: number | null,
};

/**
 *  One of a person's dice looks (ADR 0101, ADR 0107 item 11): colours as
 *  `#rrggbb`, a texture and a material from the fixed lists, nothing
 *  else — never a URL or a file. The server checks the closed form and
 *  refuses the rest; `app` makes the colours follow the viewer's palette
 *  (the "Do Verso" preset).
 */
export type DiceStyle = {
	body: string,
	number: string,
	outline: string,
	texture: string,
	material: string,
	app?: boolean | null,
};

/**  A person's dice: a style for each of the three colour slots. */
export type DiceStyles = {
	"1": DiceStyle,
	"2": DiceStyle,
	"3": DiceStyle,
};

/**
 *  One term of dice in a roll: `-1d4` is `sign` -1 and `sides` 4; a
 *  fudge die (`dF`) has three sides, -1, 0 and +1. `kept` count in the
 *  total, `dropped` were taken off by keep or drop, each in the order the
 *  dice fell.
 */
export type DiceTermRoll = {
	sign: number,
	sides: number,
	fudge: boolean,
	kept: number[],
	dropped: number[],
};

/**  One resolved link of the vault, for the graph. */
export type Edge = {
	from: string,
	to: string,
};

/**
 *  Sticker and color of an entry (note or folder), plus its first alias
 *  when one exists, and manual order and pinned lists (ADR 0060, S1, S3).
 */
export type EntryLabel = EntryLabel_Serialize | EntryLabel_Deserialize;

/**
 *  Sticker and color of an entry (note or folder), plus its first alias
 *  when one exists, and manual order and pinned lists (ADR 0060, S1, S3).
 */
export type EntryLabel_Deserialize = {
	sticker: string | null,
	color: string | null,
	alias: string | null,
	/**
	 *  Every alias, the first included (ADR 0089 item 5: the suggestion
	 *  while typing matches them).
	 */
	aliases?: string[],
	order?: string[] | null,
	pinned?: string[] | null,
};

/**
 *  Sticker and color of an entry (note or folder), plus its first alias
 *  when one exists, and manual order and pinned lists (ADR 0060, S1, S3).
 */
export type EntryLabel_Serialize = {
	sticker: string | null,
	color: string | null,
	alias: string | null,
	/**
	 *  Every alias, the first included (ADR 0089 item 5: the suggestion
	 *  while typing matches them).
	 */
	aliases?: string[],
	order?: string[] | null,
	pinned?: string[] | null,
};

/**  Why a command could not answer, by what the UI can do about it. */
export type ErrorKind = 
/**  No folder is open yet. */
"no_folder" | 
/**
 *  The path cannot name a note of the folder (absolute, `..`, hidden,
 *  ignored, empty); a folder key that is not one; a folder switch
 *  from a window that may not, or while a note window is open.
 */
"refused" | 
/**  No such file; no folder opened before has this key. */
"not_found" | 
/**  A placeholder: present, content not downloaded (ADR 0043). */
"unavailable" | 
/**
 *  A server that could not be reached: no connection made — refused,
 *  no such name, a TLS handshake that failed — or no answer in time.
 *  `message` is the server's address, `host[:port]`, as the window
 *  names it to the person; when the name was resolved to addresses,
 *  each address tried follows on a line of its own (ADR 0097), so a
 *  bad DNS reads as one. Why it could not be reached goes to the
 *  app's log (the maintainer, 2026-10-14: a server down said nothing).
 */
"unreachable" | 
/**
 *  The file's bytes are not UTF-8: no text to edit (spec Q25 is
 *  `[OPEN]`; this is the least that keeps the file safe).
 */
"not_text" | 
/**
 *  The file is not a board: not a `.canvas`, or not JSON (ADR 0057);
 *  the text view is where it gets fixed.
 */
"not_canvas" | 
/**
 *  The file on disk is not the one that was read: nothing was
 *  written; read again and show both versions (invariant 11).
 */
"changed" | 
/**  Something already stands where a note would be created or moved. */
"exists" | 
/**
 *  A new name differs only in case from an entry its folder already
 *  lists — `nota.md` beside `Nota.md`: a Mac or Windows keeps the two
 *  as one file, so nothing was made (spec Q8, decided 2026-10-12). An
 *  answer, a name to choose again — not a fault.
 */
"case_twin" | 
/**
 *  The folder's quota on its server would be passed: nothing was
 *  written; a write that shrinks the folder is always allowed (ADR
 *  0077 item 5).
 */
"quota" | 
/**
 *  A server's sensitive action wants a fresh proof that it is the
 *  person (ADR 0083 item 6): the window asks for the password and
 *  sends the action once more.
 */
"prove_first" | 
/**  The core could not answer. */
"failed" | 
/**
 *  A paired phone asked for a command that acts on the computer it is
 *  paired with, or that is the owner's (ADR 0096 item 12): no phone
 *  runs it, whatever its role.
 */
"not_on_phone" | 
/**
 *  A phone that may only read asked for a command that changes
 *  something (ADR 0096 items 6 and 12): the person lets it edit from
 *  the computer.
 */
"phone_reads";

/**
 *  What the person asking may do with a file, answered with every read and
 *  on each entry of a listing. `attach_image` is whether they may put a new
 *  image into it (*Edits* on the file, ADR 0113 K.6), `attach` a new file
 *  that is not an image (*Edits* and the right *Files*). For a folder,
 *  `create_note` and `create_board` say whether they may create a note (a
 *  base, a folder) or a board (a drawing) in it: *Edits* on the folder and
 *  the right *Creates notes* or *Creates boards*.
 */
export type FileAccess = {
	level: AccessLevel,
	attach: boolean,
	attach_image?: boolean,
	create_note?: boolean,
	create_board?: boolean,
	why: AccessWhy,
};

/**
 *  One entry of the open folder as the last walk saw it: what a folder
 *  listing shows and sorts by. `size` and `modified` are `f64` because
 *  the TypeScript side has no 64-bit integer without `bigint`: bytes are
 *  exact up to 2^53, seconds since the epoch far beyond any date.
 */
export type FileEntry = FileEntry_Serialize | FileEntry_Deserialize;

/**
 *  One entry of the open folder as the last walk saw it: what a folder
 *  listing shows and sorts by. `size` and `modified` are `f64` because
 *  the TypeScript side has no 64-bit integer without `bigint`: bytes are
 *  exact up to 2^53, seconds since the epoch far beyond any date.
 */
export type FileEntry_Deserialize = {
	path: string,
	kind: FileKind,
	/**  Bytes; 0 for a folder or an unread placeholder. */
	size: number | null,
	/**  Seconds since the Unix epoch; 0 when the file system gave none. */
	modified: number | null,
	label: EntryLabel_Deserialize | null,
	/**
	 *  What the person asking may do with it (ADR 0113 section C); a host
	 *  with no server leaves it out: the folder is the person's own.
	 */
	access?: FileAccess | null,
};

/**
 *  One entry of the open folder as the last walk saw it: what a folder
 *  listing shows and sorts by. `size` and `modified` are `f64` because
 *  the TypeScript side has no 64-bit integer without `bigint`: bytes are
 *  exact up to 2^53, seconds since the epoch far beyond any date.
 */
export type FileEntry_Serialize = {
	path: string,
	kind: FileKind,
	/**  Bytes; 0 for a folder or an unread placeholder. */
	size: number | null,
	/**  Seconds since the Unix epoch; 0 when the file system gave none. */
	modified: number | null,
	label: EntryLabel_Serialize | null,
	/**
	 *  What the person asking may do with it (ADR 0113 section C); a host
	 *  with no server leaves it out: the folder is the person's own.
	 */
	access?: FileAccess | null,
};

/**  What one entry of the open folder is. */
export type FileKind = "note" | "file" | "folder" | 
/**  Present, content in the cloud (ADR 0043). */
"placeholder";

/**
 *  Files dropped on a window from the system's file manager (T.11, decided
 *  2026-10-22; event `files-dropped`). The host catches the drop itself —
 *  the web view only ever hands bytes — and keeps the paths: the window is
 *  told where in it the drop fell (whole CSS pixels from the window's top left)
 *  and the files' names, and then asks `take_dropped` for them (rule 4: no
 *  path crosses).
 */
export type FilesDropped = {
	x: number,
	y: number,
	names: string[],
};

/**
 *  Files being dragged over a window (event `files-over`), for the window to
 *  show where a drop would land: `over` is false when the drag left. The
 *  position is in CSS pixels from the window's top left; the names are not
 *  known until the drop.
 */
export type FilesOver = {
	over: boolean,
	x: number,
	y: number,
};

/**  A named root of the file tree (ADR 0062). */
export type Focus = Focus_Serialize | Focus_Deserialize;

/**  A named root of the file tree (ADR 0062). */
export type Focus_Deserialize = {
	name: string,
	paths: string[],
	sticker?: string | null,
};

/**  A named root of the file tree (ADR 0062). */
export type Focus_Serialize = {
	name: string,
	paths: string[],
	sticker?: string | null,
};

/**  The result of reading focuses from the open folder (ADR 0062). */
export type FocusesSummary = FocusesSummary_Serialize | FocusesSummary_Deserialize;

/**  The result of reading focuses from the open folder (ADR 0062). */
export type FocusesSummary_Deserialize = {
	/**  Focuses found in `.space/waypoints.json`, or empty if no file. */
	focuses: Focus_Deserialize[],
	/**  Whether `.space/waypoints.json` is present in the open folder. */
	has_file: boolean,
	/**  Whether `.space/waypoints.json` is in the known format (ADR 0062 D6). */
	format_known: boolean,
	/**  Why the file is read-only, if not known format or unreadable. */
	read_only_reason: string | null,
	/**  Machine-readable code for read-only reason. */
	read_only_code?: ReadOnlyReasonCode | null,
	/**  The revision stamp for optimistic concurrency (Invariants 9 & 11). */
	stamp: string | null,
};

/**  The result of reading focuses from the open folder (ADR 0062). */
export type FocusesSummary_Serialize = {
	/**  Focuses found in `.space/waypoints.json`, or empty if no file. */
	focuses: Focus_Serialize[],
	/**  Whether `.space/waypoints.json` is present in the open folder. */
	has_file: boolean,
	/**  Whether `.space/waypoints.json` is in the known format (ADR 0062 D6). */
	format_known: boolean,
	/**  Why the file is read-only, if not known format or unreadable. */
	read_only_reason: string | null,
	/**  Machine-readable code for read-only reason. */
	read_only_code?: ReadOnlyReasonCode | null,
	/**  The revision stamp for optimistic concurrency (Invariants 9 & 11). */
	stamp: string | null,
};

/**
 *  The one source of "who am I here" (ADR 0113 section C), in the
 *  capabilities.
 */
export type FolderAccess = {
	seat: AccessSeat,
	/**
	 *  The role at the folder or share: `owner`, `editor`, `reader`; empty
	 *  for a visitor or a stranger.
	 */
	role: string,
	cap: AccessCap,
	/**  Whether the folder has a table at all. */
	table: boolean,
};

/**  A block with an `^id` in a note of the folder (`list_block_ids`). */
export type FolderBlock = {
	/**  The note's path, relative to the open folder. */
	path: string,
	id: string,
	kind: BlockKind,
	/**  The heading above the block, else its first line, short. */
	label: string,
	/**  `label` is the heading above the block (else its first line). */
	under_heading: boolean,
	/**  A table's body rows, or a list's top-level items (0 for the rest). */
	rows: number,
	/**  A list with a task item (`- [ ]`, `- [x]`). */
	tasks: boolean,
};

/**
 *  The `^id` blocks of the folder, and whether more were left out of a
 *  list that is bounded.
 */
export type FolderBlocks = {
	blocks: FolderBlock[],
	truncated: boolean,
};

/**
 *  What changed in the open folder, as the watcher saw it and the index
 *  then found it: the payload of the `folder-changed` event the host sends
 *  the app's windows after every batch of changes (provisional:
 *  `docs/reference/watcher-decision.md`). Notes are named by their path
 *  relative to the folder (rule 4). The lists are what this batch's index
 *  run found; another run may have found a change first, so a window
 *  checks every note it shows against the disk whatever they say — read
 *  again when nothing was typed in it, saved at once otherwise, which meets
 *  the difference (invariant 11), marked when it is gone.
 */
export type FolderChanged = {
	/**  The folder's key: a window showing another folder has nothing to do. */
	key: string,
	/**  Notes this run found new or different on disk. */
	changed: string[],
	/**  Notes this run found gone from disk. */
	removed: string[],
	/**
	 *  Entries renamed or moved, when the side knows it moved them: a
	 *  device's rename on a server (ADR 0079). A window's tab of `from`
	 *  follows it to `to`, as after a rename made in the window. The
	 *  watcher never knows a rename, and leaves this empty: the old path
	 *  is among `removed`, the new one among `changed`, as here too.
	 */
	moved?: Moved[],
	/**
	 *  Whether which entries there are, or of which kind, changed: a tree
	 *  or a folder view is drawn again only then.
	 */
	listing: boolean,
	/**  The index run's counts and problems, as `reindex` answers them. */
	index: IndexSummary,
};

/**  One data file listed. */
export type FolderDataEntry = {
	/**  `^[a-z0-9][a-z0-9-]{0,63}$`. */
	id: string,
	/**
	 *  What to hand back to change or remove the file; empty when the file
	 *  cannot be read now (a placeholder of on-demand storage, or past
	 *  its kind's bound, 256 KiB for a layout and 4 MiB for a bundle):
	 *  reading it says why.
	 */
	revision: string,
};

/**  A data file read: its text as it is on disk. */
export type FolderDataFile = {
	text: string,
	revision: string,
};

/**  Which directory of the folder's data a file is in. */
export type FolderDataKind = 
/**  `.verso/layouts/<id>.json`: a card's or statblock's layout. */
"layouts" | 
/**  `.verso/bundles/<id>.json`: a world's or campaign's template bundle. */
"bundles";

/**
 *  The data files of a kind, and the names beside them that are not a valid
 *  id. A sync conflict copy (`mesa (conflict, Mac, 2026-10-20).json`) or a
 *  hand-made `Mesa.json` is one: no command reaches it, so it is named for
 *  the person to rename (to a valid id) or remove in a file manager.
 */
export type FolderDataList = {
	entries: FolderDataEntry[],
	/**
	 *  File names (not paths) in the directory that are not `<id>.json`,
	 *  sorted, at most 50.
	 */
	strays: string[],
};

/**  The revision of the bytes a write left. */
export type FolderDataWritten = {
	revision: string,
};

/**  The folder that is open, and what indexing it did. */
export type FolderInfo = {
	/**  The folder's own name (its last path component), for display. */
	name: string,
	/**
	 *  An opaque, stable name for the folder that carries no path — the
	 *  stem of its index file's name under the configuration directory:
	 *  letters, digits and `-`. What a UI keeps its per-folder state
	 *  under, and what `reopen_folder` takes to open the folder again.
	 */
	key: string,
	index: IndexSummary,
	/**
	 *  The name of the folder's file system when changes made there by
	 *  other programs may show late: a volume without the exclusive rename
	 *  and with hard links (macOS: some network volumes; ADR 0048, revised
	 *  2026-10-12), where a file Verso creates or moves is named by a
	 *  link, whose later removal by another program the system may not
	 *  report. Verso's own writes are as safe as anywhere. The UI says it
	 *  once per folder, in the user's language (ADR 0035).
	 */
	late_outside_changes?: string | null,
};

/**  The folder's layer of settings as read now (ADR 0070 items 1–2). */
export type FolderLayer = {
	/**
	 *  Whether `.verso/settings.json` stands in the folder. When it does
	 *  not, every setting is this machine's until one is first changed.
	 */
	exists: boolean,
	/**
	 *  Why the folder's layer is not used now: `unavailable` (the file is
	 *  a placeholder of on-demand storage, ADR 0043), `invalid` (not a
	 *  JSON object) or `share` (a window on a share of a server's folder,
	 *  whose settings are the whole folder's, ADR 0081). It is never
	 *  written then, and this machine's settings apply.
	 */
	problem: string | null,
	/**
	 *  What was read, for the next change to hand back (invariant 11);
	 *  `None` when there is no file — the next change creates it.
	 */
	revision: string | null,
	settings: FolderSettings,
	/**
	 *  What the write that answered this could not confirm; empty after
	 *  a read.
	 */
	warnings: string[],
};

/**
 *  A folder at 90 % of its quota or more (event `folder-quota`, ADR 0077
 *  item 5, ADR 0084 item 7): pushed by the server after a write, to the
 *  windows on the server's folder and to a device that syncs a folder of
 *  its computer with it, which tells that folder's windows. Bytes, as
 *  numbers the window can show.
 */
export type FolderQuota = {
	/**  What the folder takes now. */
	used: number | null,
	/**  Its quota. */
	quota: number | null,
};

/**
 *  The folder's settings that travel with it (ADR 0070 items 1–2), as
 *  `.verso/settings.json` holds them, or a change to them: `None` is "not
 *  set here". Every path is relative to the folder, joined by `/`.
 */
export type FolderSettings = {
	bookmarks: string[] | null,
	/**
	 *  A plain file name without `.md`; empty: a folder's note is named
	 *  after the folder.
	 */
	folder_note_name: string | null,
	/**  Leave out the well-known build folders (ADR 0044). */
	ignore_build_dirs: boolean | null,
	/**  Honour each `.gitignore` (ADR 0044). */
	respect_gitignore: boolean | null,
	/**  The periodic notes' settings (ADR 0093 item 4). */
	periodic: PeriodicSettings | null,
	/**  The oracle's odds and spark words (ADR 0102 item 2). */
	oracle: OracleSettings | null,
	/**
	 *  The theme the folder suggests (ADR 0100 item 4): the JSON text of
	 *  one object, at most 16 KiB; an empty text takes the suggestion away.
	 *  The window checks its tokens.
	 */
	recommended_theme: string | null,
};

/**
 *  A folder of the open folder as its owner shares it (ADR 0081 item 7):
 *  the path inside the open folder — `""` for the whole folder, whose
 *  people are its members — who has access and in which role, and the
 *  attachments folder shown with it, read-only (item 11).
 */
export type FolderShare = {
	id: string | null,
	path: string,
	people: SharePerson[],
	attachments: string | null,
	/**  The share points at a folder that is gone (item 13). */
	missing: boolean,
};

/**
 *  The space a folder takes (ADR 0075 item 4): counted from the walk the
 *  index already makes, never by a walk of its own. Bytes, as numbers the
 *  window can show.
 */
export type FolderSpace = {
	/**  Every file of the folder, notes and attachments. */
	total: number | null,
	/**  The notes (`.md`). */
	notes: number | null,
	/**  Everything else: pictures, PDFs, boards, other files. */
	attachments: number | null,
	/**  How many files. */
	files: number,
	/**
	 *  The folder's index, kept beside the configuration (not inside the
	 *  folder).
	 */
	index: number | null,
};

/**
 *  A UniVerso announced on the local network (ADR 0097): what the
 *  announcement says, to show and to click, never to trust. The `url` is
 *  the address a click fills in; nothing connects because of it.
 */
export type FoundServer = {
	/**  The announced instance name, `UniVerso-ab12cd`. */
	name: string,
	/**  The announced host, `universo-ab12cd.local`. */
	host: string,
	/**
	 *  Where a click connects: the public address the server announced, or
	 *  `http://address[:port]`; empty when `needs_public_url`.
	 */
	url: string,
	/**
	 *  A server that speaks TLS itself and announced no public address: it
	 *  is listed, but cannot be offered by IP (a certificate is for a
	 *  name); the server's `VERSO_PUBLIC_URL` must be set.
	 */
	needs_public_url: boolean,
	https: boolean,
	/**  The version it announced; empty when it said none. */
	version: string,
};

/**  A heading of a note, for citing and for the outline. */
export type Heading = {
	level: number,
	text: string,
	line: number,
	col: number,
};

/**  A file's history (items 5 to 8). */
export type HistoryListing = {
	path: string,
	/**  Newest first. */
	versions: VersionEntry[],
	/**
	 *  When the file went to the trash, in milliseconds; none while it is
	 *  there (item 9).
	 */
	gone: number | null,
	/**
	 *  Whether this person may delete a version: the folder's owner and
	 *  the admin on a server; on the computer, always (item 6).
	 */
	can_delete: boolean,
	/**  How many days versions are kept; 0: no limit (item 3). */
	days: number,
	/**
	 *  The bytes the folder's history takes — shown, not counted against
	 *  the quota (item 7).
	 */
	size: number | null,
	/**  The folder's quota on its server, in bytes; none without one. */
	quota: number | null,
	/**  The history alone passed the quota: its oldest versions go early. */
	early: boolean,
	/**
	 *  Why part of the history could not be shown: a synced folder whose
	 *  server is out of reach shows this computer's versions only.
	 */
	partial: string | null,
};

/**  One search hit. */
export type Hit = {
	path: string,
	snippet: string,
};

/**
 *  Which side the window talks to (ADR 0027, ADR 0073 item 2): the app on
 *  this computer, or a server.
 */
export type Host = "desktop" | "server";

/**  Progress payload emitted during vault indexing. */
export type IndexProgress = {
	/**  "scanning" | "indexing" | "done" */
	phase: string,
	current: number,
	total: number,
	file: string | null,
};

/**
 *  What one `index` run did (ADR 0043: placeholders are present, never
 *  removed).
 */
export type IndexSummary = {
	indexed: number,
	unchanged: number,
	removed: number,
	placeholders: number,
	/**
	 *  Problems the walk met and what the run could not do besides
	 *  indexing, one readable line each with paths relative to the
	 *  folder, for the UI to show.
	 */
	problems: string[],
	/**
	 *  The folder is not watched for changes made outside the app: the
	 *  operating system's reason, as it gives it (no path). The UI says
	 *  what that means, in the user's language (ADR 0035).
	 */
	unwatched: string | null,
	/**
	 *  The folder changed and this index run could not bring the index up
	 *  to date: the core's reason. The UI says it in the user's language.
	 */
	unindexed: string | null,
};

/**  Result of an in-app update installation. */
export type InstallResult = {
	success: boolean,
	message: string,
	app_path: string | null,
	requires_restart: boolean,
};

/**  A name in one interface language (`pt-BR`, `en`), as a schema writes it. */
export type Label = {
	lang: string,
	text: string,
};

/**  A link a note makes. */
export type Link = {
	/**  As written in the note. */
	target: string,
	/**  The note it resolves to, or none. */
	resolved: string | null,
	embed: boolean,
	heading: string | null,
	block: string | null,
	alias: string | null,
	line: number,
	col: number,
	/**
	 *  Through a share, a link to a note reaches nothing the person sees
	 *  (ADR 0081 item 11): a note outside what was shared with them and a
	 *  note that does not exist answer alike, so that whether a note of
	 *  that name exists outside never crosses. Shown like an unresolved
	 *  link, as "not in what was shared with you", and never made into a
	 *  note. A file's target (`p.png`) is left to `resolve_attachment`.
	 *  Always false outside a share.
	 */
	outside?: boolean,
};

/**
 *  A note that links to what moved: its text before and after the links
 *  are pointed at the new place, with the revision `write_note` takes
 *  back. Shown, then applied, one note at a time (ADR 0048).
 */
export type LinkRewrite = {
	path: string,
	revision: string,
	before: string,
	after: string,
};

/**  One address the pairing dialog may show. */
export type LocalAddressChoice = {
	address: string,
	/**  The interface's name (`en7`, `feth237`). */
	interface: string,
	/**  `lan` (Wi-Fi, Ethernet) or `virtual` (a VPN, ZeroTier, a bridge...). */
	kind: string,
	/**
	 *  What a virtual interface probably is (`ZeroTier`, `VPN`): a guess
	 *  from its name, shown with a question mark.
	 */
	hint: string | null,
	/**  The address the system uses for its default route. */
	default_route: boolean,
};

/**  A phone that presented the token and waits for the laptop's answer. */
export type LocalAsked = {
	/**  The phone's name, as it sent it, made safe. */
	device: string,
	address: string,
	/**  When it asked, `YYYY-MM-DDTHH:MM:SSZ`. */
	asked: string,
};

/**  One line of the log of what happened, kept 365 days. */
export type LocalAudit = {
	at: number,
	action: string,
	subject: string | null,
	address: string | null,
};

/**  A folder the person may tick to serve. */
export type LocalFolder = {
	/**  The folder's opaque key (`FolderInfo.key`). */
	key: string,
	name: string,
	/**
	 *  The NAME of the directory the folder lives in (`obsidian` for
	 *  `~/Documents/obsidian/Caderno`), empty when it has none: a label
	 *  to tell two folders of the same name apart and to group the list.
	 *  A name, not a path (ADR 0026 rule 4): nothing above that one
	 *  directory crosses.
	 */
	place: string,
	ticked: boolean,
	/**
	 *  The folders inside it chosen to be served, relative to it and
	 *  `/`-joined (ADR 0096 item 2, amended 2026-10-16); none when all of it
	 *  is served. Each reaches the phone as a folder of its own.
	 */
	parts: string[],
	/**
	 *  Chosen folders the last start left out for not being on the disk any
	 *  more (they are in `parts` until the person changes them).
	 */
	missing: string[],
	/**
	 *  The vault's attachments folder that goes with the chosen folders,
	 *  read-only and files only (Obsidian's own setting, read at each
	 *  start); none when it names none, or overlaps a chosen folder.
	 */
	attachments: string | null,
	/**
	 *  The server this folder also syncs with: such a folder cannot be
	 *  served in V1 (item 11), and the row says to open that address on
	 *  the phone instead.
	 */
	syncs_with: string | null,
};

/**  The dialog's state, asked while it is open. */
export type LocalPairState = {
	open: boolean,
	remaining: number,
	asked: LocalAsked | null,
};

/**  What the pairing dialog shows. */
export type LocalPairing = {
	/**
	 *  The text the QR encodes (also copied by hand when the phone cannot
	 *  scan).
	 */
	url: string,
	/**  `address:port`, to type. */
	address: string,
	/**
	 *  Every address that could be shown, best first (the default route's,
	 *  then real networks, then virtual ones), so the person can pick
	 *  another. Empty when the host's own certificate and name are used.
	 */
	choices: LocalAddressChoice[],
	/**  The address (no port) this QR and link are for. */
	chosen: string,
	/**  The code to type when the phone cannot scan: eight letters. */
	code: string,
	/**  The QR as rows of `1` (dark) and `0`; the window draws it. */
	qr: string[],
	expires_in: number,
	fingerprint: string,
	/**
	 *  `own` or `files`: with `own`, the dialog says the limit in words
	 *  (trust on first use, for a network the person trusts).
	 */
	certificate: string,
};

/**  A phone paired with this computer. */
export type LocalPhone = {
	id: string,
	name: string,
	/**  `reader` or `editor`; never more. */
	role: string,
	/**  Seconds since the epoch (a `u32` lasts until 2106). */
	paired: number,
	last_seen: number,
	address: string,
};

/**  Where "this app is a server" stands. */
export type LocalServerStatus = {
	/**
	 *  Whether this build of the app can serve: every system (ADR 0096
	 *  item 17, revised 2026-10-15); `false` only in a stand-in that cannot.
	 */
	supported: boolean,
	serving: boolean,
	port: number | null,
	/**  The private addresses it listens on. */
	addresses: string[],
	phones_paired: number,
	phones_connected: number,
	pairing_open: boolean,
	/**
	 *  The certificate's SHA-256, in pairs and upper case, for the person
	 *  to compare.
	 */
	fingerprint: string | null,
	/**  `own` (self-signed: trust on first use) or `files` (the host's). */
	certificate: string,
	/**
	 *  Tailscale seems to run here: its own `tailscale serve` gives a
	 *  certificate a phone trusts (ADR 0073 item 6).
	 */
	tailscale: boolean,
	/**
	 *  Why serving last stopped by itself (the network changed), for the
	 *  person to read; none once it was turned on or off by hand.
	 */
	stopped_because: string | null,
	/**
	 *  This computer could not connect to its own address: a firewall is
	 *  refusing what comes in, and the section shows the steps to allow it
	 *  (item 9). The app never adds the rule itself.
	 */
	unreachable: boolean,
	/**  "Keep on at start" (item 1's separate, off-by-default switch). */
	keep_on: boolean,
	/**
	 *  The host's own certificate and key, when given (item 5 (d)), and the
	 *  name it is for.
	 */
	cert_file: string | null,
	key_file: string | null,
	host_name: string | null,
	/**
	 *  Phones connected at once, at most, 1 to 16 (item 13, amended
	 *  2026-10-16: the ceiling is a setting; the default is 4).
	 */
	max_connected: number,
	/**
	 *  Chosen folders this start left out for not being on the disk, each as
	 *  `folder/chosen`: the window says so.
	 */
	dropped: string[],
};

/**  One file the loose-files window shows (ADR 0114 item 18). */
export type LooseFileInfo = LooseFileInfo_Serialize | LooseFileInfo_Deserialize;

/**  One file the loose-files window shows (ADR 0114 item 18). */
export type LooseFileInfo_Deserialize = {
	/**
	 *  The file's name with its extension, as the window names the tab
	 *  and asks for the note (`read_note`, `write_note`): a second file of
	 *  the same name in the same window is told apart by a numbered name
	 *  (`nota (2).md`), never by a path.
	 */
	name: string,
	/**
	 *  An opaque, stable name for the file that carries no path — letters,
	 *  digits and `-`, as `FolderInfo::key` — what the window keeps its
	 *  state under and what the `folder-changed` event names.
	 */
	key: string,
	/**
	 *  The parent folder's own name, as a label beside the title: never
	 *  its path.
	 */
	place: string,
	/**  Why the file is read only, when it is. */
	read_only?: ReadOnlyReason | null,
	/**
	 *  The file's size in bytes (saturated at 4 GiB; such a file is read
	 *  only anyway).
	 */
	size: number,
	/**
	 *  The name of a folder Verso has opened before that this file lies
	 *  in, when there is one (ADR 0114 item 7 ii, Q3): the window offers
	 *  to open it. Never its path.
	 */
	known_folder?: string | null,
};

/**  One file the loose-files window shows (ADR 0114 item 18). */
export type LooseFileInfo_Serialize = {
	/**
	 *  The file's name with its extension, as the window names the tab
	 *  and asks for the note (`read_note`, `write_note`): a second file of
	 *  the same name in the same window is told apart by a numbered name
	 *  (`nota (2).md`), never by a path.
	 */
	name: string,
	/**
	 *  An opaque, stable name for the file that carries no path — letters,
	 *  digits and `-`, as `FolderInfo::key` — what the window keeps its
	 *  state under and what the `folder-changed` event names.
	 */
	key: string,
	/**
	 *  The parent folder's own name, as a label beside the title: never
	 *  its path.
	 */
	place: string,
	/**  Why the file is read only, when it is. */
	read_only?: ReadOnlyReason | null,
	/**
	 *  The file's size in bytes (saturated at 4 GiB; such a file is read
	 *  only anyway).
	 */
	size: number,
	/**
	 *  The name of a folder Verso has opened before that this file lies
	 *  in, when there is one (ADR 0114 item 7 ii, Q3): the window offers
	 *  to open it. Never its path.
	 */
	known_folder?: string | null,
};

/**  The tiles of a map's picture. */
export type MapInfo = {
	state: MapState,
	/**  The picture's size in pixels; 0 when it is not known. */
	width: number,
	height: number,
	/**  The side of a tile. */
	tile: number,
	/**
	 *  The levels of the pyramid: level 0 is the picture at its own size,
	 *  each one above half the one below, the last small enough for one
	 *  tile.
	 */
	levels: number,
	/**
	 *  The tiles cut so far and in all (a count of `f64` for the
	 *  TypeScript side, as sizes are).
	 */
	done: number | null,
	total: number | null,
	message: string,
};

/**  How a map's picture stands. */
export type MapState = 
/**  Small enough to be drawn whole, as any picture is. */
"whole" | 
/**  Being cut into tiles: ask again. */
"cutting" | 
/**  Cut: the tiles are there. */
"ready" | 
/**
 *  Large, and in a format that cannot be cut (only a PNG can): drawn
 *  whole, with a warning.
 */
"unsupported" | 
/**  Could not be cut (`message` says why): drawn whole. */
"failed";

/**  What adding the folder's server to Claude Desktop did. */
export type McpAdded = {
	server: string,
	/**  An entry by that name was there and was replaced. */
	replaced: boolean,
	/**  The name of the copy of the configuration as it was, beside it. */
	backup: string | null,
	warnings: string[],
};

/**  How an MCP client's configuration stands with this folder's entry. */
export type McpClientState = 
/**  The client is not installed. */
"noClient" | 
/**  No entry for this folder. */
"absent" | 
/**  The entry is there, as the app would write it. */
"same" | 
/**  An entry by that name starts something else. */
"different";

/**
 *  The open folder's MCP server as clients name it, and whether Claude
 *  Desktop knows it.
 */
export type McpStatus = {
	/**  The name of the server in a client's configuration: `verso-<folder>`. */
	server: string,
	claude: McpClientState,
	/**
	 *  What a client starts for it, as "Add to Claude" would write it: the
	 *  linked command line, or on Windows the bundled `verso.exe` by its
	 *  path — shown to the person before it is written (ADR 0054).
	 */
	command: string,
};

/**
 *  A note's name written plainly in another note: one unlinked mention
 *  (ADR 0089 item 1), the name or one of its aliases as a phrase on word
 *  boundaries, case ignored and accents kept, in prose only.
 */
export type Mention = {
	/**  The note that mentions. */
	path: string,
	/**
	 *  1-based line, and 1-based column in Unicode scalar values (spec
	 *  §4.4), of the mention's first character.
	 */
	line: number,
	col: number,
	/**  The mention as written. */
	text: string,
	/**  Up to 60 characters of its line before it and after it. */
	before: string,
	after: string,
	/**
	 *  The text is one of the note's aliases, not its name: the link
	 *  keeps it as the link's text.
	 */
	alias: boolean,
	/**  In a table's cell: the link's `|` is written `\|`. */
	table: boolean,
	/**
	 *  Inside a `> [!secret]` callout (ADR 0087): never in a reader's
	 *  answer from a server.
	 */
	secret: boolean,
};

/**
 *  A note's unlinked mentions, in path and position order; `more` when
 *  there were more than the answer holds.
 */
export type Mentions = {
	mentions: Mention[],
	more: boolean,
};

/**
 *  One row of a menu, as the window gets it (Windows and Linux draw the
 *  menu inside the window; macOS has the native bar and never asks).
 */
export type MenuEntry = {
	/**
	 *  "sep", "command" (a command of the window's registry, `id`), "own"
	 *  (the host's own, run by the window: `id` names the action) or
	 *  "system" (an editing or window action of the web view).
	 */
	kind: string,
	id: string,
	label: string,
	/**  The feature switch (ADR 0103) that must be on for the row to show. */
	feature: string | null,
	/**
	 *  The fixed key of an own or system row, as the window writes it
	 *  (`Mod-z`); a command's key is the window's, as bound now.
	 */
	key: string | null,
};

export type MenuSection = {
	key: string,
	title: string,
	/**  The letter that opens it with Alt. */
	mnemonic: string,
	items: MenuEntry[],
};

/**
 *  A link of a note that no note answers to, for the graph's option of
 *  showing them (spec Q14, decision B): the note it is written in and the
 *  name it points at, as written (the smallest spelling in byte order when
 *  several notes spell it differently, so every source shows one node).
 */
export type MissingLink = {
	from: string,
	target: string,
};

/**  A file that moved, from one relative path to another. */
export type Moved = {
	from: string,
	to: string,
};

/**
 *  What moving several entries at once left — a selection of the tree
 *  dropped on a folder (ADR 0048, revised 2026-10-07): those that moved;
 *  those the disk refused, each with its error, which stayed where they
 *  were; one plan of rewrites over where everything ended; the notes it
 *  could not plan; what could not be confirmed; and what moved by a rule
 *  of its own (a folder's note). Empty when nothing had to move.
 */
export type MovedEntries = {
	moved: Moved[],
	refused: RefusedEntry[],
	rewrites: LinkRewrite[],
	skipped: Skipped[],
	warnings: string[],
	also: Moved[],
};

/**  A note's text as it is on disk now, with what the index knows of it. */
export type NoteText = NoteText_Serialize | NoteText_Deserialize;

/**  A note's text as it is on disk now, with what the index knows of it. */
export type NoteText_Deserialize = {
	path: string,
	/**  Without line endings; line `n` (1-based) is `lines[n - 1]`. */
	lines: string[],
	/**
	 *  The note rendered as HTML by the core's own parser, for a preview:
	 *  wikilinks are `<a class="wikilink" data-target>`, embeds
	 *  `<span class="embed" data-target>`; the UI resolves targets
	 *  through `links`.
	 */
	html: string,
	/**
	 *  The frontmatter as a properties panel shows it: key and one line
	 *  of text per value, in the order written.
	 */
	properties: Property[],
	/**
	 *  The whole text as read, line endings included: what the editor
	 *  gives back is written as is, no normalization (ADR 0012). A file
	 *  whose bytes are not UTF-8 gives no text at all (`not_text`).
	 */
	text: string,
	/**
	 *  Opaque: what was read. `write_note` takes it back and refuses a
	 *  file that changed meanwhile (invariant 11, `changed`).
	 */
	revision: string,
	headings: Heading[],
	blocks: Block[],
	/**
	 *  The file differs from what the index holds: graph answers may be
	 *  behind this text.
	 */
	stale: boolean,
	/**
	 *  The index holds the note only as a last known version: a
	 *  placeholder stood where it was (ADR 0043).
	 */
	unverified: boolean,
	/**
	 *  The note's type, when its `type:` names a schema of the folder
	 *  (ADR 0052); null for plain Markdown.
	 */
	note_type: NoteType | null,
	/**
	 *  The `verso-schema` blocks this note holds: one that types nothing,
	 *  or a nested one that is not read, is said in its note (ADR 0052).
	 */
	schema_blocks: SchemaNotice[],
	/**
	 *  What the person asking may do with it (ADR 0113 section C); a host
	 *  with no server leaves it out: the folder is the person's own.
	 */
	access?: FileAccess | null,
};

/**  A note's text as it is on disk now, with what the index knows of it. */
export type NoteText_Serialize = {
	path: string,
	/**  Without line endings; line `n` (1-based) is `lines[n - 1]`. */
	lines: string[],
	/**
	 *  The note rendered as HTML by the core's own parser, for a preview:
	 *  wikilinks are `<a class="wikilink" data-target>`, embeds
	 *  `<span class="embed" data-target>`; the UI resolves targets
	 *  through `links`.
	 */
	html: string,
	/**
	 *  The frontmatter as a properties panel shows it: key and one line
	 *  of text per value, in the order written.
	 */
	properties: Property[],
	/**
	 *  The whole text as read, line endings included: what the editor
	 *  gives back is written as is, no normalization (ADR 0012). A file
	 *  whose bytes are not UTF-8 gives no text at all (`not_text`).
	 */
	text: string,
	/**
	 *  Opaque: what was read. `write_note` takes it back and refuses a
	 *  file that changed meanwhile (invariant 11, `changed`).
	 */
	revision: string,
	headings: Heading[],
	blocks: Block[],
	/**
	 *  The file differs from what the index holds: graph answers may be
	 *  behind this text.
	 */
	stale: boolean,
	/**
	 *  The index holds the note only as a last known version: a
	 *  placeholder stood where it was (ADR 0043).
	 */
	unverified: boolean,
	/**
	 *  The note's type, when its `type:` names a schema of the folder
	 *  (ADR 0052); null for plain Markdown.
	 */
	note_type: NoteType | null,
	/**
	 *  The `verso-schema` blocks this note holds: one that types nothing,
	 *  or a nested one that is not read, is said in its note (ADR 0052).
	 */
	schema_blocks: SchemaNotice[],
	/**
	 *  What the person asking may do with it (ADR 0113 section C); a host
	 *  with no server leaves it out: the folder is the person's own.
	 */
	access?: FileAccess | null,
};

/**  A note's type (ADR 0052): its `type:` as written, and what it reaches. */
export type NoteType = {
	written: string,
	state: TypeState,
};

/**
 *  Obsidian's settings for daily and periodic notes, as their files hold
 *  them (ADR 0093 item 11): the core Daily notes plugin's
 *  `.obsidian/daily-notes.json` and the Periodic Notes plugin's
 *  `.obsidian/plugins/periodic-notes/data.json`, read once and never
 *  written. Each is its file's text, `None` when it is not there, not
 *  readable now or not text; `unavailable` names the ones that are a
 *  placeholder of on-demand storage.
 */
export type ObsidianPeriodic = {
	daily_notes: string | null,
	periodic_notes: string | null,
	unavailable: string[],
};

/**
 *  What the app was handed and opened: a folder, as always, or one file
 *  (ADR 0114 item 18).
 */
export type Opened = Opened_Serialize | Opened_Deserialize;

/**
 *  What the app was handed and opened: a folder, as always, or one file
 *  (ADR 0114 item 18).
 */
export type Opened_Deserialize = { kind: "folder"; info: FolderInfo } | { kind: "file"; info: LooseFileInfo_Deserialize };

/**
 *  What the app was handed and opened: a folder, as always, or one file
 *  (ADR 0114 item 18).
 */
export type Opened_Serialize = { kind: "folder"; info: FolderInfo } | { kind: "file"; info: LooseFileInfo_Serialize };

/**
 *  What a window asks the server of a room to draw for the oracle (ADR
 *  0102 item 5): the window sends what it draws from, the server draws —
 *  its generator, never the window's — and the room hears the result.
 */
export type OracleAsk = 
/**
 *  A yes/no question: the odds row it is asked at, six whole numbers
 *  adding to 100 (yes-and, yes, yes-but, no-but, no, no-and); a d100
 *  is read against it.
 */
{ kind: "question"; odds: number[] } | 
/**  Two pairs of words from the lists in use, one word of each list. */
{ kind: "spark"; lists: OracleSparks } | 
/**  One entry of a table, as many sides as it has entries. */
{ kind: "table"; entries: string[] };

/**
 *  What the server drew for an [`OracleAsk`], stamped with the account's
 *  name; nothing is written, to the file or the database. The question's
 *  own text never reaches the server.
 */
export type OracleDraw = {
	/**  `question`, `spark` or `table`. */
	kind: string,
	/**
	 *  A question: the d100 face, 1 to 100. A table: the entry's place,
	 *  counted from 1. A spark: 0.
	 */
	roll: number,
	/**  A question: the answer's column, 0 (yes-and) to 5 (no-and). */
	answer: number | null,
	/**  A spark: action, theme, descriptor, focus. A table: the entry. */
	words: string[],
	/**  The name of the account that asked. */
	by: string,
	/**  When, RFC 3339 in UTC. */
	at: string,
};

/**
 *  The oracle's odds table and spark words when the folder changed them
 *  (ADR 0102 item 2), or a change to them: `None` is "not set here".
 */
export type OracleSettings = {
	/**
	 *  Five rows (nearly certain, likely, even, unlikely, nearly
	 *  impossible), each six non-negative integers adding to 100: yes-and,
	 *  yes, yes-but, no-but, no, no-and. Wider than any row can use so that
	 *  a number out of range reaches the core and is refused there with its
	 *  message, not by the host's argument decoding.
	 */
	odds: number[][] | null,
	sparks: OracleSparks | null,
	/**
	 *  `true` removes `oracle.odds` from the file; `None` in `odds` is "no
	 *  change", so it cannot say this. Refused together with `odds`.
	 */
	clear_odds: boolean | null,
	/**  `true` removes `oracle.sparks` from the file, likewise. */
	clear_sparks: boolean | null,
};

/**
 *  The spark word lists of the oracle, or a change to them: all four at
 *  once, each of 1 to 200 words of 1 to 60 characters.
 */
export type OracleSparks = {
	action: string[],
	theme: string[],
	descriptor: string[],
	focus: string[],
};

/**  One period's settings, or a change to them: `None` is "not set here". */
export type PeriodSettings = {
	/**  Whether the period is on: its command, its marks in the calendar. */
	on: boolean | null,
	/**
	 *  A Moment.js format string of the subset Verso reads (item 2); a `/`
	 *  in it makes folders.
	 */
	format: string | null,
	/**
	 *  The folder its notes are kept in, relative to the folder and joined
	 *  by `/`; empty: the folder's root. Not set: the day's folder (item 3).
	 */
	folder: string | null,
	/**
	 *  The template note, by its path relative to the folder or its name
	 *  in the templates folder; empty or not set: the built rule (item 6).
	 */
	template: string | null,
};

/**
 *  The periodic notes' settings of a folder (ADR 0093 items 1–6), or a
 *  change to them: what a change sets replaces what the file says, every
 *  other key kept.
 */
export type PeriodicSettings = {
	day: PeriodSettings | null,
	week: PeriodSettings | null,
	month: PeriodSettings | null,
	quarter: PeriodSettings | null,
	year: PeriodSettings | null,
	/**  The week's first day, `sunday` … `saturday` (item 5). */
	week_start: string | null,
	/**
	 *  The language month and weekday names are written in, `pt-BR` or
	 *  `en` (item 5).
	 */
	language: string | null,
};

/**  Why a chosen file was not read. */
export type PickSkip = 
/**  A directory or another entry that is not a file. */
"not_a_file" | 
/**  Kept in the cloud, not on this computer (ADR 0043). */
"placeholder" | 
/**  Larger than one file may be (or the choice as a whole was). */
"too_large" | 
/**  The system refused the read. */
"unreadable";

/**
 *  One file the person chose with the system's file picker ("Import
 *  files…", A11Y.10): its name and either its bytes or a token, never the
 *  path it came from (ADR 0026 rule 4). On a window of this computer's own
 *  folder the file stays where it is and the token stands for it:
 *  `create_picked` copies it into the folder on the host's side, so that a
 *  large file never crosses as base64. On a window of a server's folder the
 *  bytes are in `base64` and the window creates the file through
 *  `create_file`, as a file dropped on the tree. Exactly one of the two.
 */
export type PickedFile = {
	name: string,
	base64: string | null,
	token: string | null,
};

/**
 *  What the system's file picker gave: the files read, and those left out.
 *  Both empty when the picker was cancelled.
 */
export type PickedFiles = {
	files: PickedFile[],
	skipped: SkippedPick[],
};

/**
 *  What bringing placeholders down would take, asked before it starts (ADR
 *  0043, decided 2026-10-27): the size of the files named, and the room the
 *  disk has left. Bytes are `f64`, as everywhere in the contract.
 */
export type PlaceholderPlan = {
	/**
	 *  The files named that are placeholders now, and their logical sizes
	 *  added.
	 */
	count: number,
	bytes: number | null,
	/**
	 *  The bytes the disk under the folder can still take; `None` when the
	 *  system would not say (the window then refuses to download: it
	 *  cannot tell the files fit).
	 */
	free: number | null,
};

/**
 *  What a channel plays: a file of the folder (`kind` `file`, `path`
 *  relative to the folder the window opened, never absolute, never `..`).
 */
export type PlaybackSource = {
	kind: string,
	path: string,
};

/**  One frontmatter key and its value. */
export type Property = {
	key: string,
	value: PropertyValue,
};

/**
 *  A frontmatter value, typed as the YAML gave it, for a properties
 *  panel that shows a list as pills and a boolean as a checkbox. A number
 *  crosses as its text, so the panel shows what was written.
 */
export type PropertyValue = { kind: "text"; value: string } | { kind: "number"; value: string } | { kind: "checkbox"; value: boolean } | 
/**  A list of plain strings; any other list is `Nested`. */
{ kind: "list"; value: string[] } | 
/**
 *  A mapping, or a list with an item that is not a plain string,
 *  flattened to one line: shown, never edited by the panel — written
 *  back as text it would change type.
 */
{ kind: "nested"; value: string } | 
/**  `key:` with nothing after it (YAML null). */
{ kind: "empty" };

/**
 *  A live read link, as the owner's panel lists it (ADR 0105 item 5).
 *  Times are seconds since the Unix epoch.
 */
export type ReadLinkInfo = {
	id: string,
	/**  `folder` or `note`. */
	kind: string,
	/**
	 *  The folder's or the note's path in the open folder; `""` is the
	 *  whole folder.
	 */
	path: string,
	/**  Who made it (item 3). */
	made_by: string,
	made_at: number | null,
	expires: number | null,
	has_password: boolean,
	last_opened: number | null,
	/**  How many pages hold it open now. */
	open: number,
};

/**  A link just made: its address is in `url`, once and nowhere else. */
export type ReadLinkMade = {
	/**  The whole address, `<server>/r/<token>`, to give to whoever reads. */
	url: string,
	link: ReadLinkInfo,
};

/**
 *  The read links of the open folder, and whether the server has them on
 *  (the administrator's switch, item 3).
 */
export type ReadLinks = {
	enabled: boolean,
	links: ReadLinkInfo[],
};

/**
 *  Why a loose file opens for reading only (ADR 0114 items 12 and 13).
 *  A file that mixes line endings, or whose bytes are not UTF-8, is said
 *  by the note's own text as in a folder.
 */
export type ReadOnlyReason = 
/**
 *  The file or its folder cannot be written by this person:
 *  permissions, a locked file, a read-only volume.
 */
"permissions" | 
/**
 *  Above the bound a loose file is edited under (8 MiB, as built;
 *  Q9): shown in Source, read only.
 */
"too_large";

/**  Machine-readable code for the reason `.space/waypoints.json` is read-only (ADR 0062). */
export type ReadOnlyReasonCode = "cloud_placeholder" | "invalid_json" | "unknown_format";

/**
 *  A file opened without a folder lately (ADR 0114 item 15, Q4), for the
 *  window's own menu on Windows and Linux: its name, where it sits (the
 *  shortened label `RecentFolder::place` uses) and its place in the host's
 *  list, which `open_recent_file` takes back. Never a path.
 */
export type RecentFile = {
	index: number,
	name: string,
	place: string,
};

/**
 *  A folder of this computer opened before, for the folder switcher's
 *  "On this computer" (ADR 0081 item 5): its name, the key
 *  `reopen_folder` takes and a short label of where it lives — never its
 *  path (ADR 0026 rule 4).
 */
export type RecentFolder = {
	key: string,
	name: string,
	/**
	 *  Where the folder sits, to tell two of one name apart: its parent
	 *  shortened to `~/…/Documents/obsidian`, `…/Volumes/Disco` — never
	 *  absolute, never with `..`, and empty when there is nothing to say.
	 */
	place: string,
};

/**  An entry a move left where it was, and why. */
export type RefusedEntry = {
	path: string,
	error: ContractError,
};

/**
 *  What a rename or a move left: the new path, the rewrites it calls for,
 *  the notes it could not plan, and what could not be confirmed once the
 *  entry had moved (a durability step, the index following, the
 *  sidecar), one line each. The move happened whenever this is answered.
 */
export type Renamed = {
	path: string,
	rewrites: LinkRewrite[],
	skipped: Skipped[],
	warnings: string[],
	/**
	 *  What else moved with the entry, by a rule of its own: a folder's
	 *  note taking the folder's new name (ADR 0060). Old path to new.
	 */
	also: Moved[],
};

/**  Where a restore put an entry of the bin (ADR 0080 item 5). */
export type Restored = {
	path: string,
	/**  The original path was taken: it went beside it, under a new name. */
	beside: boolean,
	warnings: string[],
};

/**  A `verso-schema` block of a note. */
export type SchemaNotice = {
	/**  The line of the opening fence (1-based). */
	line: number,
	name: string | null,
	/**  Inside a list or a quote: not read. */
	nested: boolean,
	/**  Why a block at the top level types nothing (`unknown_kind`, …). */
	error: string | null,
};

/**
 *  A server this app signed in to (ADR 0074 item 8; the maintainer's
 *  answer K of 2026-10-09): its address and whose account it is. The
 *  device's token stays on this side.
 */
export type ServerAccount = {
	url: string,
	email: string,
	name: string,
};

/**
 *  The window's server is back after it was gone (event `server-back`,
 *  ADR 0084 item 10): the folder was opened again.
 */
export type ServerBack = {
	url: string,
};

/**  A folder of a server the account may open, and the role in it. */
export type ServerFolder = {
	id: string,
	name: string,
	role: string,
	/**
	 *  Whose it is, when it is someone else's — a whole folder or a share
	 *  (ADR 0081 item 5): it is listed under "Shared with me".
	 */
	owner?: string | null,
	/**
	 *  A folder inside someone's folder, shared with this account (ADR
	 *  0081 item 2).
	 */
	share?: boolean,
	/**  The shared folder is no longer where the share points (item 13). */
	missing?: boolean,
};

/**
 *  The folders a server lists for the account, and whether the account may
 *  make a new one there (the server's `mayCreate`, ADR 0074 item 6; the
 *  maintainer, 2026-10-16: a new server has no folder, and the admin who
 *  signs the app in has to be able to make the first).
 */
export type ServerFolders = {
	folders: ServerFolder[],
	may_create?: boolean,
};

/**
 *  The window's server, or what it held there, is gone (event
 *  `server-gone`, ADR 0084 item 10): said by the desktop app to a window
 *  on a server's folder.
 */
export type ServerGone = {
	/**  The server, as signed in to (Settings › Servers). */
	url: string,
	/**
	 *  What ended: `session` (the server ended this device's session, or
	 *  refused it on reconnecting), `folder` (this account no longer
	 *  reaches the folder or the share: `reason` says why), `connection`
	 *  (the connection dropped; the app tries again), `unreachable` (a
	 *  try found the server out of reach: `address` names it) or `closed`
	 *  (the table is closed by its game master: the app tries again and
	 *  gets in when it opens).
	 */
	what: string,
	/**
	 *  With `folder`, when the server says it: `revoked` by its owner,
	 *  `deleted` (the shared folder went), `left` by the person.
	 */
	reason: string | null,
	/**
	 *  With `unreachable`: the server's address, `host[:port]`, and the
	 *  addresses tried, each on a line after it (as `Unreachable`'s
	 *  message).
	 */
	address: string | null,
};

/**
 *  A sign-in under way: the code the server's page shows, to compare, and
 *  the page the app opened in the browser.
 */
export type ServerSignIn = {
	code: string,
	page: string,
};

/**
 *  Where a window reaches the server whose folder it shows (`window_server`):
 *  its address as the app is signed in to it, and the folder's id there. What
 *  turns a link the server made without knowing its own public name (a path
 *  like `/invite/<token>`) into one that opens, and gives a note's address
 *  in the server's window. In a browser it is the page's own origin.
 */
export type ServerWindow = {
	url: string,
	folder: string,
};

/**
 *  A folder given to this account by another person (event `share-given`,
 *  ADR 0084 item 7): a share of a folder inside theirs (ADR 0081), or
 *  their whole folder. Pushed by the server to the account's open
 *  connections — its browser windows and its devices, never a token's —
 *  when the account had no access to it before; a role changed later is
 *  not this event.
 */
export type ShareGiven = {
	/**
	 *  What opens it: the id of a share, or of the whole folder
	 *  (`ServerFolder::id`).
	 */
	id: string,
	/**
	 *  The folder's own name: the shared folder's last component, or the
	 *  whole folder's name.
	 */
	name: string,
	/**
	 *  `editor` (writes) or `reader` (reads only); `owner` for a whole
	 *  folder given with that role.
	 */
	role: string,
	/**  The display name of the person who gave it. */
	by: string,
	/**  A share inside someone's folder, not their whole folder. */
	share: boolean,
	/**
	 *  The server, as signed in to (Settings › Servers): the desktop app
	 *  fills it, being signed in to any number of servers; none from the
	 *  server itself, whose windows are on it.
	 */
	server: string | null,
};

/**
 *  A person who has access to a shared folder, and in which role (ADR
 *  0081 item 7).
 */
export type SharePerson = {
	id: string,
	name: string,
	email: string,
	/**  `owner`, `editor` (writes) or `reader` (reads only). */
	role: string,
};

/**  Why a note that links to what moved got no rewrite. */
export type SkipReason = 
/**  A placeholder: present, content not downloaded (ADR 0043). */
"unavailable" | 
/**  Not UTF-8: no text can be rewritten without loss. */
"not_text" | 
/**  Could not be read; the error is among the warnings. */
"failed";

/**
 *  A note the plan could not cover: it links to what moved, and its links
 *  may now point elsewhere or nowhere, but no rewrite could be made. The
 *  UI lists them.
 */
export type Skipped = {
	path: string,
	reason: SkipReason,
};

/**  A chosen file that was left out, and why. */
export type SkippedPick = {
	name: string,
	reason: PickSkip,
};

/**  One thing that crossed. */
export type SyncLogEntry = {
	/**  `YYYY-MM-DDTHH:MM:SSZ`. */
	at: string,
	/**
	 *  `sent`, `received`, `deleted_there`, `deleted_here`,
	 *  `renamed_there`, `renamed_here`, `conflict` or `merged` (two
	 *  appends to a note joined, ADR 0079 item 8).
	 */
	what: string,
	path: string,
	/**  The other path of a rename, or a conflict's copy. */
	other: string | null,
	/**
	 *  For what came from the server — received, deleted or renamed here,
	 *  a conflict, a merge — who made the change there, as the server's
	 *  log says it (sync 2): the person's name, and the name of the
	 *  device whose sync made it. Either may be unknown: a change made in
	 *  a browser has no device, one found on the server's disk no one, a
	 *  share says neither.
	 */
	by: string | null,
	device: string | null,
};

/**  A file sync left out, and why. */
export type SyncRefused = {
	path: string,
	/**
	 *  `reader`, `quota`, `placeholder`, `too_large`, `name_taken`,
	 *  `case_twin_there` (two names on the server that differ only in
	 *  case: this computer keeps one, spec Q8), `name_invalid`, `changed`
	 *  or `failed`.
	 */
	reason: string,
	message: string,
};

/**
 *  What the synced desktop last heard of one file (ADR 0113 S8): the same
 *  answer the server gives a window, kept by the host while the link is
 *  down.
 */
export type SyncRight = {
	path: string,
	access: FileAccess,
};

/**
 *  `sync_rights`: the files of the open synced folder the host knows what
 *  the person may do with. A path it has no answer for is left out, and
 *  the window keeps to its default. `fresh` is false while the server's
 *  answer is being asked again (access or the role changed): the window
 *  asks once more when the sync has passed.
 */
export type SyncRights = {
	fresh: boolean,
	files: SyncRight[],
};

/**
 *  A folder's sync with a server, as its window shows it (ADR 0079 item
 *  13): the status bar's state and the folder settings' section.
 */
export type SyncStatus = {
	/**
	 *  The folder of this computer it is of (`FolderInfo::key`): every
	 *  window hears every folder's, and shows its own.
	 */
	key: string,
	/**  Whether the folder syncs at all. */
	on: boolean,
	/**  The server, as signed in to (Settings › Servers). */
	server: string,
	/**  The server's folder: its id and its name there. */
	folder: string,
	folder_name: string,
	/**
	 *  The role there: `owner`, `editor` or `reader` (a reader only
	 *  receives, item 1).
	 */
	role: string,
	/**
	 *  `off`, `starting`, `synced`, `syncing`, `offline`, `paused` or
	 *  `error`.
	 */
	state: string,
	/**  Files on their way in this pass. */
	sending: number,
	receiving: number,
	/**  When paused for deletions, how many it would delete (item 9). */
	deletions: number | null,
	/**  The conflict copies in the folder (item 8), by path. */
	conflicts: string[],
	/**  Files not synced, each with its reason (item 13). */
	refused: SyncRefused[],
	/**
	 *  Files that are only in the cloud on this computer (a placeholder of
	 *  on-demand storage) and that sync already has a copy of: the server
	 *  holds it, nothing is asked of the person, and the window says so
	 *  quietly, apart from `refused` (ADR 0043, decided 2026-10-27).
	 */
	cloud_only: string[],
	/**  What crossed lately, newest first. */
	log: SyncLogEntry[],
	/**  When the last pass ended, `YYYY-MM-DDTHH:MM:SSZ`. */
	last: string | null,
	/**  The last error, said (in English, for the log). */
	message: string | null,
	/**
	 *  What the last error was, for the window to say in its language:
	 *  `not_signed_in`, `signed_out`, `version`, `folder_gone`, `table_closed`, `failed`;
	 *  with the state `off`, `revoked`.
	 */
	problem: string | null,
	/**
	 *  With the problem `version`: what each side runs — two builds of one
	 *  version can differ in their contracts, and the window names both.
	 */
	versions: SyncVersions | null,
	/**
	 *  When the folder's owner revoked the share this folder synced,
	 *  `YYYY-MM-DDTHH:MM:SSZ`: sync was turned off then, the files here
	 *  kept (ADR 0081 item 8). Said until sync is turned on again.
	 */
	revoked: string | null,
	/**
	 *  With a cloud (ADR 0104) instead of a UniVerso: which one and where,
	 *  and what a deletion there means. `None` for a UniVerso.
	 */
	cloud: CloudStatus | null,
};

/**
 *  What the server and this app run, when their contracts differ: the
 *  version, the commit it was built from, and the contract's hash.
 */
export type SyncVersions = {
	server_version: string,
	server_build: string,
	server_contract: string,
	app_version: string,
	app_build: string,
	app_contract: string,
};

/**
 *  The table cleared (event `table-cleared`); `keep_pinned` says whether
 *  the pinned entries stayed.
 */
export type TableCleared = {
	table: string,
	keep_pinned: boolean,
};

/**
 *  One entry of the table, as a window may see it. `kind` is `roll`
 *  (`roll` set, also a random table's: `roll.source`), `oracle` (`draw`
 *  set), `say` (`text` set), `image` (`image` set: the file's path in the
 *  folder), `file` (a PDF or audio: `image` holds the file's path too; ADR
 *  0113 K.4) or `secret` ("<name> rolled in secret": nothing else set).
 */
export type TableEntry = {
	/**
	 *  The table it belongs to: its folder inside the server's folder,
	 *  `""` for the folder itself.
	 */
	table: string,
	/**
	 *  The server's number for it: decimal digits, growing; the cursor of
	 *  `table_history`.
	 */
	id: string,
	kind: string,
	/**  The author's name, stamped by the server. */
	by: string,
	/**  The author's account, opaque: `TableJoin.you` is the window's own. */
	by_id: string,
	/**  When, RFC 3339 in UTC, the server's clock. */
	at: string,
	/**  The note it was made from, relative to the folder. */
	path: string | null,
	pinned: boolean,
	/**
	 *  A roll "to the owner": shown in full to its roller and the folder's
	 *  owners only.
	 */
	secret: boolean,
	roll: DiceRoll | null,
	draw: OracleDraw | null,
	text: string | null,
	image: string | null,
};

/**
 *  A right to send to the chat changed for this account (event
 *  `table-images`): told to its windows at the table at once.
 */
export type TableImages = {
	table: string,
	images: boolean,
	files?: boolean,
};

/**
 *  What `table_join` answers: who the window is, its role, the latest
 *  entries with every pinned one (oldest first), whether older ones
 *  exist, and who is at the table.
 */
export type TableJoin = {
	/**  The table joined, as the server names it (`""`: the folder itself). */
	table: string,
	you: string,
	/**  `owner`, `editor` or `reader`. */
	role: string,
	entries: TableEntry[],
	more: boolean,
	roster: TableMember[],
	/**
	 *  Whether this account may send an image to the table: an owner always,
	 *  a player when the game master gave it *Images* (ADR 0113 K.6).
	 */
	images?: boolean,
	/**
	 *  Whether this account may send a file that is not an image: an owner
	 *  always, a player when given *Files* (K.6).
	 */
	files?: boolean,
	/**
	 *  Whether this window's person controls the table's music: the game
	 *  master (ADR 0116 item 22, `may(Play)`).
	 */
	play?: boolean,
	/**
	 *  What each channel plays now, as this window may know it (ADR 0116
	 *  item 8): a joiner and a reconnecting window start from the truth.
	 */
	playback?: TablePlayback[],
	/**
	 *  Whether this window's person may share live audio to the table: the
	 *  game master (ADR 0116 item 22, `may(Broadcast)`).
	 */
	broadcast?: boolean,
	/**
	 *  The table's live share now, if any (ADR 0116 section B): a joiner
	 *  and a reconnecting window start from the truth.
	 */
	share?: AudioShare | null,
};

/**  Who is at the table: one per account, however many windows. */
export type TableMember = {
	name: string,
	by_id: string,
	/**  The presence colour, `#rrggbb`. */
	color: string,
	styles: DiceStyles | null,
};

/**  A page of older entries (`table_history`), oldest first. */
export type TablePage = {
	entries: TableEntry[],
	more: boolean,
};

/**  An entry pinned or unpinned (event `table-pinned`). */
export type TablePinned = {
	table: string,
	id: string,
	pinned: boolean,
};

/**
 *  One channel's playback, as one window may know it (event
 *  `table-playback`, `TableJoin.playback`, the answer of the controls).
 *  The server stamps `anchor_ms` with its own clock and grows `revision`
 *  at each change; a window plays `position_ms + (server now - anchor_ms)`
 *  while `state` is `playing`.
 */
export type TablePlayback = {
	/**
	 *  The table: its folder inside the server's folder, `""` for the
	 *  folder itself (as `TableEntry.table`).
	 */
	table: string,
	/**  `music` (V1's one channel). */
	channel: string,
	/**  Grows at every change; a control naming an older one is refused. */
	revision: number | null,
	/**
	 *  What plays; none when nothing does, or when this window's person
	 *  does not see the file (`unseen`): not its name, not its path.
	 */
	source: PlaybackSource | null,
	/**
	 *  The track plays, but this person does not see its file and hears
	 *  nothing (ADR 0116 item 9).
	 */
	unseen: boolean,
	/**  `playing`, `paused` or `stopped`. */
	state: string,
	/**  The position, in milliseconds, at the server's instant `anchor_ms`. */
	position_ms: number | null,
	/**  The server's clock, Unix milliseconds, when `position_ms` held. */
	anchor_ms: number | null,
	/**  The game master's volume of the channel, 0 to 100. */
	master: number,
	looping: boolean,
	/**
	 *  The track's length as the game master's window read it; none when
	 *  it is not known yet.
	 */
	duration_ms: number | null,
	/**
	 *  Who last changed it: the name and the opaque account, stamped by the
	 *  server.
	 */
	by: string,
	by_id: string,
	/**
	 *  To the game master only: the names of the people at the table who do
	 *  not see the file, and of those whose window cannot play it. Empty to
	 *  everyone else.
	 */
	unheard: string[],
	cannot: string[],
};

/**
 *  What `table_play` answers. With `ask`, when some players of the table
 *  do not see the file, nothing is played and `unheard` names them, for the
 *  game master to release the file or play without them.
 */
export type TablePlayed = {
	playback: TablePlayback | null,
	unheard: string[],
};

/**  An entry deleted (event `table-removed`). */
export type TableRemoved = {
	table: string,
	id: string,
};

/**  Who is at a table (event `table-roster`): one per account. */
export type TableRoster = {
	table: string,
	members: TableMember[],
};

/**
 *  The server's clock (`table_time`), Unix milliseconds: the window keeps
 *  its offset from it, as NTP does (ADR 0116 item 10).
 */
export type TableTime = {
	now_ms: number | null,
};

/**  A tag and the notes that carry it. */
export type Tag = {
	name: string,
	notes: string[],
};

/**
 *  Where the shell started (ADR 0115, Q4 decided 2026-10-31): in the
 *  folder of this computer the window shows — a synced one included, it is
 *  files on this disk (ADR 0079) — or, for a server's folder with no copy
 *  here, in the person's home directory, which the window says in a line.
 */
export type TerminalAt = "folder" | "home";

/**
 *  One terminal of this app, as the window names it: opaque, unique for the
 *  app's run, so that a layout brought back after a restart never names a
 *  terminal of another run.
 */
export type TerminalId = string;

/**  A terminal started or found again after a reload of the window. */
export type TerminalOpened = {
	id: TerminalId,
	at: TerminalAt,
	/**
	 *  The shell's program name, for the tab (`zsh`, `pwsh`): a name, never
	 *  its path.
	 */
	shell: string,
};

/**
 *  What a terminal sends the window on its channel: the text the shell
 *  printed (UTF-8, never a character cut between two messages), or its end,
 *  with the exit code when the system gave one.
 */
export type TerminalOutput = { kind: "data"; text: string } | { kind: "ended"; code: number | null };

/**
 *  The shell to start on Windows (ADR 0115, Q7 decided 2026-10-31):
 *  PowerShell — `pwsh.exe` when found, else `powershell.exe` — or the
 *  Command Prompt, chosen in Settings › Terminal and agents. Elsewhere the
 *  person's `$SHELL` is started whatever this says.
 */
export type TerminalShell = "powershell" | "cmd";

/**  The terminal's size in character cells. */
export type TerminalSize = {
	cols: number,
	rows: number,
};

/**  How the window asks a terminal to start (ADR 0115 items 4, 5 and 14). */
export type TerminalStart = {
	size: TerminalSize,
	/**
	 *  A folder below the open one, relative to it ("Open terminal here");
	 *  none is the folder's root (Q2).
	 */
	folder: string | null,
	/**  An AI tool to start in it, its command typed in once the shell runs. */
	cli: AiCli | null,
	/**  Windows: which shell (Q7); none is PowerShell. */
	shell: TerminalShell | null,
	/**
	 *  The system's language as the window has it (`pt-BR`), for `LANG`
	 *  where the app was started without one.
	 */
	locale: string | null,
};

/**
 *  Any file of the folder as text, with the revision `write_text` takes
 *  back (invariant 11): the editor of files that are not notes.
 */
export type TextFile = TextFile_Serialize | TextFile_Deserialize;

/**
 *  Any file of the folder as text, with the revision `write_text` takes
 *  back (invariant 11): the editor of files that are not notes.
 */
export type TextFile_Deserialize = {
	path: string,
	text: string,
	revision: string,
	/**  What the write could not preserve, one line each; empty after a read. */
	warnings: string[],
	/**
	 *  What the person asking may do with it (ADR 0113 section C); a host
	 *  with no server leaves it out: the folder is the person's own.
	 */
	access?: FileAccess | null,
};

/**
 *  Any file of the folder as text, with the revision `write_text` takes
 *  back (invariant 11): the editor of files that are not notes.
 */
export type TextFile_Serialize = {
	path: string,
	text: string,
	revision: string,
	/**  What the write could not preserve, one line each; empty after a read. */
	warnings: string[],
	/**
	 *  What the person asking may do with it (ADR 0113 section C); a host
	 *  with no server leaves it out: the folder is the person's own.
	 */
	access?: FileAccess | null,
};

/**
 *  One entry of the folder's bin (ADR 0080 item 4): a file, or a folder
 *  trashed whole, with what is known of its deletion.
 */
export type TrashEntry = {
	/**  Where it is, under `.trash/`: what a restore or a removal names. */
	path: string,
	/**  Where it was, relative to the folder. */
	original: string,
	/**  A folder trashed with what it held. */
	folder: boolean,
	/**  The bytes it holds. */
	size: number | null,
	/**
	 *  When it was deleted, in seconds since the Unix epoch; when that is
	 *  not known (`known` false), when it was first seen in the bin.
	 */
	deleted: number | null,
	known: boolean,
	/**
	 *  Who deleted it: on a server the account (or, for a version a write
	 *  replaced, the device); on the computer the server whose sync
	 *  carried the deletion out. None: this computer, or not known.
	 */
	by: string | null,
	/**  Sync carried the deletion out on this computer (item 9). */
	sync: boolean,
	/**  Not deleted: the version a device's write replaced (item 12). */
	replaced: boolean,
	/**
	 *  When it is removed for good, in seconds; none when deleted files
	 *  are kept for ever.
	 */
	expires: number | null,
};

/**  The folder's bin as its page shows it (ADR 0080 items 3, 4, 7 and 8). */
export type TrashListing = {
	/**  Newest first. */
	entries: TrashEntry[],
	/**  The bytes the bin holds — shown, not counted against the quota. */
	size: number | null,
	/**  How many days deleted files are kept; 0: for ever. */
	days: number,
	/**
	 *  The most days this person may choose (a server folder's owner
	 *  shortens what the admin set, item 3); none: anything, for ever too.
	 */
	most: number | null,
	/**  Whether this person may change how long deleted files are kept. */
	can_set: boolean,
	/**
	 *  Whether this person may delete an entry now or empty the bin: the
	 *  folder's owner (item 7); on the computer, always.
	 */
	can_purge: boolean,
	/**  The folder's quota on its server, in bytes; none without one. */
	quota: number | null,
	/**
	 *  The bin alone is larger than the quota: its oldest entries expire
	 *  early (item 8).
	 */
	early: boolean,
};

/**
 *  What a deletion left: where the entry went in `.trash/`, and what
 *  could not be confirmed once it was there, one line each.
 */
export type Trashed = {
	path: string,
	warnings: string[],
};

/**
 *  What a note's `type:` reaches: one schema, read (`typed`); two or more
 *  of one name, which type nothing (`conflict`, ADR 0052 point 5); or one
 *  that does not parse (`invalid`).
 */
export type TypeState = { kind: "typed"; 
/**  The note that holds the schema. */
schema: string; 
/**  The schema's `type`, as written there. */
name: string; 
/**  The type's name per interface language. */
labels: Label[]; 
/**  The declared properties, in the schema's order. */
properties: TypedProperty[]; 
/**
 *  The layout the schema names: `infobox`, the properties as a
 *  card beside the text (ADR 0086 item 2); null, the panel as it
 *  is.
 */
layout: string | null } | { kind: "conflict"; 
/**  The notes that hold a schema of that name, in path order. */
schemas: string[] } | { kind: "invalid"; schema: string; 
/**  Why, as spec §4.8 names the kinds (`unknown_kind`, `yaml`, …). */
error: string };

/**  A property a schema declares, as the note holds it. */
export type TypedProperty = {
	key: string,
	/**
	 *  `text`, `list`, `number`, `checkbox`, `date`, `datetime`, `link` or
	 *  `image` (ADR 0086 item 1).
	 */
	kind: string,
	labels: Label[],
	/**  The note has the key. */
	present: boolean,
	/**  Its value fits the kind; false for a key the note lacks. */
	fits: boolean,
};

/**  Information about an application update. */
export type UpdateInfo = {
	/**  The currently running version (e.g. "0.2.0-beta.2"). */
	current_version: string,
	/**  The latest version available on GitHub (e.g. "0.2.0-beta.3"). */
	latest_version: string,
	/**  Whether an update is available (latest_version > current_version). */
	has_update: boolean,
	/**  Release title (e.g. "Verso Beta 0.2.0-beta.3"). */
	release_name: string,
	/**  Changelog / release notes in Markdown. */
	release_notes: string,
	/**  Direct asset download URL (or browser download url). */
	download_url: string | null,
	/**  GitHub API asset URL (used for authenticated downloads if repo is private). */
	asset_url: string | null,
	/**  Name of the download file (e.g. "Verso-Beta-0.2.0-beta.3-macos-arm64.zip"). */
	asset_name: string | null,
	/**  Size of the asset in bytes. */
	asset_size: number | null,
	/**  ISO 8601 publication timestamp. */
	published_at: string | null,
};

/**  Download progress payload emitted during update downloads. */
export type UpdateProgress = {
	downloaded_bytes: number | null,
	total_bytes: number | null,
	percent: number | null,
	/**  "downloading" | "extracting" | "installing" | "done" | "error" */
	status: string,
	message: string | null,
};

export type VersionAuthor = {
	kind: AuthorKind,
	/**  Empty for [`AuthorKind::Outside`]. */
	name: string,
};

/**  One version of a file. */
export type VersionEntry = {
	/**
	 *  Opaque: what `history_read`, `history_restore` and
	 *  `history_delete` take back.
	 */
	id: string,
	/**  When it was written, in milliseconds since the epoch. */
	at: number | null,
	authors: VersionAuthor[],
	kind: VersionKind,
	/**  The bytes of this version. */
	size: number | null,
	/**
	 *  Their SHA-256, lowercase hex: a synced folder's computer tells by
	 *  it what has crossed to the server (item 8).
	 */
	hash: string,
	/**  Lines added and removed against the version before it. */
	added: number,
	removed: number,
	/**
	 *  The file's path when this version was written (a rename since
	 *  shows here).
	 */
	path: string,
	/**
	 *  Only on this computer: not yet crossed to the server of a synced
	 *  folder (item 8).
	 */
	here_only: boolean,
};

/**  What made a version. */
export type VersionKind = 
/**  A write through Verso: a device's sync, a token, a panel. */
"write" | 
/**  The editor's saves, ten minutes of them in one version. */
"edit" | 
/**  Writing together in a note's room, ten minutes in one version. */
"room" | 
/**  A version brought back: itself a version. */
"restore" | 
/**  Changed outside Verso. */
"outside" | 
/**  The file as it was when its history began. */
"found";

/**  Where a version brought back landed, and its revision now. */
export type VersionRestored = {
	path: string,
	revision: string,
};

/**  A version's text. */
export type VersionText = {
	id: string,
	/**  None when its bytes are not UTF-8: shown by its size only. */
	text: string | null,
	size: number | null,
};

/**  A note that is a web page: its path and the address in its `url`. */
export type WebNote = {
	path: string,
	url: string,
};

/**
 *  Where a web page goes, as an iframe would put it. `slot` is the
 *  page's whole box: its size is the page's viewport (`100vh` is its
 *  height), and it may reach outside its pane or the window. `visible` is
 *  the part of the slot that shows — inside every scroller around it and
 *  the window, clear of the tab bar and the status bar (`embedPlace`,
 *  app/ui/src/leaves/embedClip.ts). The page is drawn at `slot` and only
 *  inside `visible` (`web_clip`); scrolling the note moves the slot and
 *  never scrolls the page. A web note's own view sends one rectangle
 *  twice.
 */
export type WebPlace = {
	slot: WebRect,
	visible: WebRect,
};

/**
 *  A rectangle in the window's logical pixels, from the top-left of the
 *  window's page.
 */
export type WebRect = {
	x: number | null,
	y: number | null,
	w: number | null,
	h: number | null,
};

/**
 *  What a write left behind: the note as written — the text that was
 *  sent, with the revision of those very bytes, never a re-read — and
 *  what the atomic write could not guarantee, one line each (permissions,
 *  owner, extended attributes, hard links, network file system,
 *  durability). None means the content was lost; all are for the user
 *  to see.
 */
export type Written = Written_Serialize | Written_Deserialize;

/**
 *  What a write left behind: the note as written — the text that was
 *  sent, with the revision of those very bytes, never a re-read — and
 *  what the atomic write could not guarantee, one line each (permissions,
 *  owner, extended attributes, hard links, network file system,
 *  durability). None means the content was lost; all are for the user
 *  to see.
 */
export type Written_Deserialize = {
	note: NoteText_Deserialize,
	warnings: string[],
};

/**
 *  What a write left behind: the note as written — the text that was
 *  sent, with the revision of those very bytes, never a re-read — and
 *  what the atomic write could not guarantee, one line each (permissions,
 *  owner, extended attributes, hard links, network file system,
 *  durability). None means the content was lost; all are for the user
 *  to see.
 */
export type Written_Serialize = {
	note: NoteText_Serialize,
	warnings: string[],
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

